def _concept_as_dict(concept_card):
    """concept_card가 dict·JSON 문자열 어느 쪽으로 와도 dict로 통일."""
    if isinstance(concept_card, dict):
        return concept_card
    if isinstance(concept_card, str) and concept_card.strip().startswith("{"):
        try:
            import json as _json
            d = _json.loads(concept_card)
            return d if isinstance(d, dict) else {}
        except Exception:
            return {}
    return {}


def resolve_world_type(concept_card):
    """작품의 세계 유형 키 — enum 강제.

    우선순위: concept_card["world_type"](유효 키일 때) → 공식 기본값 → 중원_강호
    """
    cc = _concept_as_dict(concept_card)
    wt = str(cc.get("world_type") or "").strip()
    if wt in WORLD_TYPES:
        return wt
    fk = str(cc.get("formula_key") or cc.get("wuxia_formula_main") or "").strip()
    if fk in FORMULA_DEFAULT_WORLD:
        return FORMULA_DEFAULT_WORLD[fk]
    return "중원_강호"


def resolve_fantasy_level(concept_card, ep_number=0):
    """회차의 판타지 수위 (0~3) — 세계 유형 허용 범위로 클램프.

    concept_card 필드:
      fantasy_level        기본 수위 (없으면 세계 유형 기본값)
      fantasy_peak_level   클라이맥스 구간 수위 (선택)
      fantasy_peak_from_ep 클라이맥스 구간 시작 회차 (선택)
    """
    cc = _concept_as_dict(concept_card)
    wt = resolve_world_type(cc)
    spec = WORLD_TYPES[wt]
    allowed = spec["allowed_fantasy_levels"]

    def _clamp(v, fallback):
        try:
            v = int(v)
        except (TypeError, ValueError):
            return fallback
        if v in allowed:
            return v
        return max(allowed) if v > max(allowed) else min(allowed)

    base = _clamp(cc.get("fantasy_level"), spec["default_fantasy_level"])
    peak = cc.get("fantasy_peak_level")
    from_ep = cc.get("fantasy_peak_from_ep")
    try:
        ep = int(ep_number or 0)
        from_ep = int(from_ep) if from_ep not in (None, "") else 0
    except (TypeError, ValueError):
        ep, from_ep = 0, 0
    if peak not in (None, "") and from_ep > 0 and ep >= from_ep:
        return max(base, _clamp(peak, base))
    return base


def build_fantasy_level_block(concept_card, ep_number=0):
    """판타지 수위 블록 — 이번 회차에서 무공이 어디까지 초인적인가."""
    cc = _concept_as_dict(concept_card)
    lv = resolve_fantasy_level(cc, ep_number)
    spec = FANTASY_LEVELS[lv]
    lines = [f"## 판타지 수위 — {spec['label']} (A33)"]
    if ep_number:
        lines[0] += f" · EP{ep_number}"
    lines.append(f"- 허용: {spec['allowed']}")
    if spec["forbidden_terms"]:
        lines.append("- 이번 회차 사용 금지 표현: " + " · ".join(spec["forbidden_terms"]))
    lines.append(f"- 원칙: {spec['note']}")
    peak = cc.get("fantasy_peak_level")
    from_ep = cc.get("fantasy_peak_from_ep")
    if peak not in (None, "") and from_ep not in (None, "", 0):
        lines.append(f"- 작품 설계: EP{from_ep}부터 수위 {peak} 구간. 그 전에 앞당겨 쓰지 말 것.")
    return "\n".join(lines)


def build_world_bible_block(concept_card):
    """작가가 확정한 세계관 바이블 필드만 주입. 빈 필드는 '미정'으로 표시.

    원칙 M: 빈 필드를 LLM이 채우게 두면 매번 다른 설정을 지어낸다.
    그래서 미정 항목은 '본문에서 새로 정하지 말 것'으로 명시한다.
    """
    cc = _concept_as_dict(concept_card)
    wt = resolve_world_type(cc)
    bible = cc.get("world_bible") if isinstance(cc.get("world_bible"), dict) else {}
    fields = WORLD_TYPES[wt]["bible_fields"]
    filled, pending = [], []
    for key, label, _guide in fields:
        val = bible.get(key)
        if isinstance(val, str) and val.strip():
            filled.append(f"- **{label}**: {val.strip()}")
        else:
            pending.append(label)
    if not filled and not pending:
        return ""
    lines = [f"## 🌐 세계관 바이블 — {WORLD_TYPES[wt]['label']} (작가 확정 · 임의 변경 금지)"]
    lines.extend(filled if filled else ["- (작가 확정 항목 없음)"])
    if pending:
        lines.append("")
        lines.append("### 미정 항목 — 본문에서 새로 정하지 말 것")
        lines.append("아래 항목은 작가가 아직 정하지 않았다. 이번 회차에서 이 항목에 관한")
        lines.append("새 규칙·새 기관·새 수치를 만들어 내지 않는다. 필요하면 언급을 피한다.")
        lines.append("- " + " / ".join(pending))
    return "\n".join(lines)


def build_world_type_block(concept_card, ep_number=0):
    """세계 유형 기본 설정 + 학원 서브시스템 + 세계관 바이블 + 판타지 수위.

    v2.9.0: Arc·플롯·집필·재집필 프롬프트의 WUXIA_CLASSIC_WORLDBUILDING
    무조건 주입을 이 함수로 교체한다.
    """
    cc = _concept_as_dict(concept_card)
    wt = resolve_world_type(cc)
    base = globals().get(WORLD_TYPES[wt]["base_block"], "")
    parts = [f"# 세계 유형: {WORLD_TYPES[wt]['label']} ({wt})", base]
    fk = str(cc.get("formula_key") or "").strip()
    if fk == "F4_학원_무협":
        parts.append(WUXIA_ACADEMY_SYSTEM)
    bible_block = build_world_bible_block(cc)
    if bible_block:
        parts.append(bible_block)
    parts.append(build_fantasy_level_block(cc, ep_number))
    return "\n\n".join(p for p in parts if p)


# 판타지 수위 0~1 작품의 EP1~EP4 장르 계약 — 실전 무예 신호
HISTORICAL_OPENING_DENSITY_SPEC = """[EP1~EP4 장르 밀도 규격 — 실전 무예 (판타지 수위 0~1)]

## 이 규격이 존재하는 이유
수위 0~1 작품의 독자는 1~4화에서 "칼이 진짜로 무겁다"를 판정한다.
이름 붙은 초식을 쏟아내는 중원 무협 쿼터를 적용하면 매 회 가짜 초식이
지어져 장르가 무너진다. 이 규격은 A29 쿼터표를 대체한다.

## 이번 회차에 반드시 채울 쿼터
□ 실존 기예명 또는 바이블 등록 무예명 **2회 이상** (본국검·쌍수도·월도 등)
□ 자세·거리·발·호흡이 보이는 무예 교환 **1장면 이상**
□ 제도 좌표 — 군영·관청·관직 이름 **2회 이상**
□ 시대 좌표 — 왕대·연도·실존 사건 **1회 이상**
□ 대가 — 부상·피로·무기 손상 등 몸의 현실 **1회 이상**

## 절대 하지 말 것
✗ 기운이 몸 밖으로 뻗는 묘사 (수위 1 이하)
✗ 바이블에 없는 초식명을 새로 짓기
✗ 경지 서열(삼류~생사경)로 실력 표시
✗ 바이블에 없는 실존 인물의 관직·연대를 만들어 내기
"""


def build_opening_density_spec(concept_card, ep_number):
    """EP1~EP4 밀도 규격 선택 — 수위 2 이상은 기존 A29 규격, 0~1은 실전 무예 규격."""
    try:
        ep = int(ep_number or 0)
    except (TypeError, ValueError):
        ep = 0
    if ep not in (1, 2, 3, 4):
        return ""
    if resolve_fantasy_level(concept_card, ep) <= 1:
        return HISTORICAL_OPENING_DENSITY_SPEC
    return WUXIA_OPENING_DENSITY_SPEC


def build_density_override_block(concept_card, ep_number=0):
    """수위 0~1 작품에서 A29 쿼터표를 무효화하는 지시. 수위 2 이상은 빈 문자열."""
    if resolve_fantasy_level(concept_card, ep_number) >= 2:
        return ""
    return (
        "## A29 쿼터표 적용 제외 (판타지 수위 0~1)\n"
        "이 작품은 실전 무예 수위다. AI 문체 규칙의 A29 정량 쿼터표"
        "(무공 명명 5종·한자 병기 8~15회·경지 노출 등)는 적용하지 않는다.\n"
        "대신 HISTORICAL 밀도 규격(기예명·자세와 거리·제도 좌표·시대 좌표·대가)을 따른다.\n"
        "A30 3박자는 '명명 → 시연 → 해설'에서 해설을 원리 대신 "
        "'그 기예를 어디서 누구에게 배웠는가'로 바꿔 적용한다."
    )


def build_world_bible_prompt(brief_text, concept_card, world_type=None, author_direction="", canon_excerpt=""):
    """기획서 → 세계관 바이블 초안 (v2.9.0). 빈 칸만 채우는 용도.

    원칙 M: 기획서에 없는 내용은 지어내지 않고 pending으로 돌린다.
    출력 키는 세계 유형의 bible_fields 키와 1:1.
    """
    cc = _concept_as_dict(concept_card)
    wt = world_type if world_type in WORLD_TYPES else resolve_world_type(cc)
    fields = WORLD_TYPES[wt]["bible_fields"]
    field_lines = "\n".join(f"- {k}: {label} — {guide}" for k, label, guide in fields)
    keys_json = ",\n".join(f'    "{k}": ""' for k, _l, _g in fields)
    brief = (brief_text or "")[:MAX_WORLD_BIBLE_BRIEF_CHARS]
    try:
        import json as _json
        cc_txt = _json.dumps({
            k: cc.get(k) for k in ("title", "logline", "genre", "formula_key",
                                   "world_setting", "setting", "competition_rules")
            if cc.get(k)
        }, ensure_ascii=False)[:6000]
    except Exception:
        cc_txt = ""

    _dir = author_direction or cc.get("author_direction", "")
    return f"""{build_author_direction_block(_dir, canon_excerpt)}

다음 기획서와 컨셉 카드에서 **세계관 바이블** 항목을 추출하세요.
세계 유형: {WORLD_TYPES[wt]['label']} ({wt})

## 추출 항목 (키: 의미 — 담을 내용)
{field_lines}

## 컨셉 카드 (요약)
{cc_txt}

## 기획서
{brief}

## 출력 형식 — 아래 JSON 객체만 출력
{{
  "fields": {{
{keys_json}
  }},
  "pending": []
}}

## 규칙
- 기획서·컨셉 카드에 **근거가 있는 내용만** 채운다. 근거가 없으면 "" 로 두고
  그 키 이름을 pending 배열에 넣는다.
- 그럴듯한 설정을 새로 지어내지 않는다. 비워 두는 것이 정답이다.
- 고유명사는 기획서 철자 그대로 (한자 병기 포함).
- 각 값은 2~4문장. 마크다운·주석·가이드 문구를 값에 넣지 않는다.
- pending에는 키 이름만 넣는다 (예: ["authority", "economy"]).
- JSON 외 텍스트 금지. 코드 블록 금지."""


MAX_WORLD_BIBLE_BRIEF_CHARS = 12000


# ═══════════════════════════════════════════════════
# v2.10.0 — 통합 시작 · 작가 방향 메모 · 서사 장치 3종
# ───────────────────────────────────────────────────
# [사고 원인 1] 작가가 1차 기획서를 버리고 방향을 고쳤는데, 엔진에는
#   "고친 방향"을 넣을 칸이 없었다. 엔진은 버린 기획서로 컨셉 카드·
#   Core Arc·캐릭터 바이블을 만들었고, 아무 경고도 없었다.
#   → 작가 방향 메모(author_direction): 기획서보다 우선하는 1순위 입력
# [사고 원인 2] 캐릭터 바이블 양식이 "메인 빌런"을 필수로 요구해,
#   기획서에 이름 있는 악역이 없으면 엔진이 매번 새 인물을 지어냈다
#   (아미고: 7/25 강무진 → 7/27 서정록). 원칙 M 재발.
# [사고 원인 3] 여러 스승에게 배워 최강이 되는 주인공(곽정형)과
#   "본인은 모르는 힘"이 한 겹씩 드러나는 구조를 관리할 장치가 없었다.
#   → 사사 대장 · 그릇 각성 · 레퍼런스 차별 규칙
# ═══════════════════════════════════════════════════

AUTHOR_DIRECTION_MAX_CHARS = 10000   # v2.11.0: 4000 → 10000 (채택표 포함 시 잘림 방지)
CANON_EXCERPT_PER_EP = 1500
CANON_EXCERPT_MAX_EPS = 4


def build_author_direction_block(author_direction="", canon_excerpt=""):
    """작가 방향 메모 + 확정 원고 발췌 — 모든 기획·집필 프롬프트의 최상단 블록.

    우선순위 (v2.12.0): 작가 방향 메모·채택표 > 기획서 > 작가 원고(참고·기준선)
    """
    d = (author_direction or "").strip()[:AUTHOR_DIRECTION_MAX_CHARS]
    c = (canon_excerpt or "").strip()
    if not d and not c:
        return ""
    lines = ["## 🧭 작가 확정 방향 — 최우선 (기획서와 충돌하면 이것을 따른다)"]
    if d:
        lines.append(d)
    if c:
        lines.append("")
        lines.append("### 작가 원고 발췌 — 참고 · 기준선 (v2.12.0)")
        lines.append("문체·장면 밀도의 기준선이다. 인물 이름·관계는 따르되, 장면·사건 배치는 예시이므로 "
                     "기준표를 더 잘 충족하는 설계가 있으면 바꿀 수 있다. 이 원고보다 못하면 안 된다.")
        lines.append(c)
    lines.append("")
    lines.append("### 우선순위 규칙")
    lines.append("1. 작가 방향 메모·채택표  2. 기획서  3. 작가 원고(참고·기준선)  4. 그 밖의 참고 자료")
    lines.append("- 아래 기획서의 설정이 위 메모와 다르면 기획서 쪽을 버린다.")
    lines.append("- 메모·원고·기획서 어디에도 없는 인물·조직·설정은 새로 만들지 않는다.")
    return "\n".join(lines)


def build_canon_excerpt(episodes, per_ep=CANON_EXCERPT_PER_EP, max_eps=CANON_EXCERPT_MAX_EPS):
    """확정 원고 dict({ep: text})에서 회차별 앞부분 발췌. 키 타입(int/str) 모두 허용."""
    if not isinstance(episodes, dict) or not episodes:
        return ""
    items = []
    for k, v in episodes.items():
        try:
            items.append((int(k), v))
        except (TypeError, ValueError):
            continue
    items.sort()
    out = []
    for ep, text in items[:max_eps]:
        t = (text or "").strip()
        if not t:
            continue
        body = t[:per_ep] + ("\n[...이하 생략...]" if len(t) > per_ep else "")
        out.append(f"[EP{ep} 작가 원고(참고) · {len(t):,}자 중 앞부분]\n{body}")
    return "\n\n".join(out)


# 서사 장치 3종 — 컨셉 카드 필드 스키마 (키 고정)
NARRATIVE_DEVICE_FIELDS = {
    "mentorship_ledger": {
        "label": "사사 대장 — 누구에게 무엇을 언제 배우는가",
        "columns": [("mentor", "스승"), ("art", "전수 무공"), ("ep", "회차"),
                    ("learns_to", "주인공식 소화 — 무엇을 배우고 무엇을 덜어내는가")],
    },
    "awakening_graph": {
        "label": "그릇 각성 — 원래 지닌 힘이 언제 한 겹씩 드러나는가",
        "columns": [("layer", "겹"), ("manifestation", "드러나는 장면"), ("ep", "회차"),
                    ("witness", "목격자"), ("cost", "대가"),
                    ("keywords", "검출 단어 (쉼표 구분)")],
    },
    "reference_diff": {
        "label": "레퍼런스 차별 규칙 — 닮은 작품과 반드시 달라야 할 점",
        "columns": [("reference", "닮은 작품·인물"), ("same", "같은 점"),
                    ("must_differ", "반드시 달라야 할 점")],
    },
}


def _device_rows(cc, key):
    rows = cc.get(key) if isinstance(cc, dict) else None
    if not isinstance(rows, list):
        return []
    return [r for r in rows if isinstance(r, dict) and any(str(v or "").strip() for v in r.values())]


def _ep_of(row):
    try:
        return int(str(row.get("ep", "")).strip().split("~")[0].split("-")[0])
    except (TypeError, ValueError, AttributeError):
        return 0


def build_narrative_device_block(concept_card, ep_number=0):
    """서사 장치 3종을 프롬프트 블록으로. ep_number=0이면 전체(Core Arc용).

    회차가 주어지면 '이미 배운 무공 / 아직 배우지 않은 무공',
    '이미 드러난 겹 / 아직 감출 겹'을 나눠서 지시한다.
    """
    cc = _concept_as_dict(concept_card)
    led = _device_rows(cc, "mentorship_ledger")
    awk = _device_rows(cc, "awakening_graph")
    ref = _device_rows(cc, "reference_diff")
    if not (led or awk or ref):
        return ""
    try:
        ep = int(ep_number or 0)
    except (TypeError, ValueError):
        ep = 0
    lines = ["## 📐 서사 장치 (작가 설계 — 임의 변경 금지)"]

    if led:
        lines.append("")
        lines.append("### 사사 대장 — 주인공은 아래 순서대로 배운다")
        if ep:
            learned = [r for r in led if 0 < _ep_of(r) <= ep]
            upcoming = [r for r in led if _ep_of(r) > ep]
            undated = [r for r in led if _ep_of(r) == 0]
            for r in learned:
                lines.append(f"- [습득] EP{_ep_of(r)} {r.get('mentor','')} → {r.get('art','')} / 소화: {r.get('learns_to','')}")
            for r in upcoming:
                lines.append(f"- [아직 배우지 않음 · EP{_ep_of(r)} 예정] {r.get('mentor','')}의 {r.get('art','')} — 이번 회차에 주인공이 이 무공을 쓰면 안 된다")
            for r in undated:
                lines.append(f"- [시점 미정] {r.get('mentor','')} → {r.get('art','')} — 회차를 새로 정하지 말 것")
        else:
            for r in led:
                lines.append(f"- EP{r.get('ep','?')} {r.get('mentor','')} → {r.get('art','')} / 소화: {r.get('learns_to','')}")
        lines.append("- 스승에게 배우는 장면은 '무엇을 덜어내는 법을 배웠는가'까지 보여준다.")

    if awk:
        lines.append("")
        lines.append("### 그릇 각성 — 원래 지닌 힘은 아래 순서로만 드러난다")
        for r in awk:
            e = _ep_of(r)
            if ep and e and e > ep:
                lines.append(f"- [감출 것 · EP{e} 예정] {r.get('layer','')} — 이번 회차에 암시만 허용, 드러내지 말 것")
            else:
                lines.append(
                    f"- {'[이미 드러남] ' if ep and e and e <= ep else ''}EP{r.get('ep','?')} "
                    f"{r.get('layer','')}: {r.get('manifestation','')} / 목격 {r.get('witness','')} / 대가 {r.get('cost','')}"
                )
        lines.append("- 각성에는 대가가 따른다. 대가 없는 각성은 쓰지 않는다.")

    if ref:
        lines.append("")
        lines.append("### 레퍼런스 차별 규칙 — 장면이 닮은 작품 쪽으로 미끄러지지 않게")
        for r in ref:
            lines.append(f"- {r.get('reference','')}: 같은 점 [{r.get('same','')}] / **반드시 다르게** [{r.get('must_differ','')}]")
    return "\n".join(lines)


def build_narrative_devices_prompt(brief_text, concept_card, author_direction="",
                                   canon_excerpt=""):
    """서사 장치 3종 초안 — 근거 있는 것만. 회차가 근거 없으면 ep는 ""."""
    cc = _concept_as_dict(concept_card)
    brief = (brief_text or "")[:MAX_WORLD_BIBLE_BRIEF_CHARS]
    try:
        import json as _json
        cc_txt = _json.dumps({k: cc.get(k) for k in (
            "title", "logline", "protagonist", "mentor", "key_supporting_chars",
            "world_setting", "core_concept_notes") if cc.get(k)}, ensure_ascii=False)[:7000]
    except Exception:
        cc_txt = ""
    return f"""{build_author_direction_block(author_direction, canon_excerpt)}

다음 자료에서 이 작품의 **서사 장치 3종** 초안을 추출하세요.

## 컨셉 카드 (요약)
{cc_txt}

## 기획서
{brief}

## 추출 대상
1. mentorship_ledger — 주인공이 누구에게 어떤 무공을 배우는가.
   learns_to: 주인공이 그 가르침을 자기 식으로 어떻게 소화하는가
   (예: 이미 힘이 넘치는 주인공이라면 '위력을 줄이는 법')
2. awakening_graph — 주인공이 원래 지닌 힘(혈통·체질·기보)이 드러나는 순서.
   layer(겹 이름) / manifestation(드러나는 장면) / witness(목격자) /
   cost(대가) / keywords(본문에서 그 힘을 가리키는 고유 단어 배열)
3. reference_diff — 자료에 언급된 닮은 작품·인물과, 같은 점 / 반드시 달라야 할 점

## 출력 형식 — 아래 JSON 객체만
{{
  "mentorship_ledger": [{{"mentor": "", "art": "", "ep": "", "learns_to": ""}}],
  "awakening_graph": [{{"layer": "", "manifestation": "", "ep": "", "witness": "", "cost": "", "keywords": []}}],
  "reference_diff": [{{"reference": "", "same": "", "must_differ": ""}}],
  "pending": []
}}

## 규칙
- 작가 방향 메모 > 기획서 > 작가 원고(참고) 순으로 따른다.
- 자료에 근거가 있는 항목만 쓴다. 회차 번호가 자료에 없으면 ep는 "" 로 둔다.
- 근거가 없어 비운 칸·빠진 항목은 pending 배열에 짧게 적는다 (예: "서아 창술 전수 회차").
- 새 스승·새 무공·새 레퍼런스를 지어내지 않는다.
- 고유명사는 자료 철자 그대로. JSON 외 텍스트 금지."""


