def get_motif_block(primary_motif="", secondary_motif=""):
    """주요 모티프 블록 생성."""
    blocks = []
    for label, motif_key in [("1차 모티프", primary_motif), ("2차 모티프", secondary_motif)]:
        if motif_key and motif_key in NARRATIVE_MOTIFS:
            m = NARRATIVE_MOTIFS[motif_key]
            blocks.append(f"**{label} · {motif_key}**: {m['desc']}\n  활용: {m['usage']}")
    if blocks:
        return "## 서사 모티프\n" + "\n\n".join(blocks)
    return ""


# ═══════════════════════════════════════════════════
# 캐릭터 플래그 (무협 특화)
# ═══════════════════════════════════════════════════

def get_character_flags_block(concept_dict):
    """
    컨셉 카드에서 캐릭터 플래그 추출해 블록 생성.
    무협 특화: 정파/사파/마교, 음성/양성 내공, 문파/낭인 등
    """
    flags = []

    protagonist = concept_dict.get("protagonist", {})
    if protagonist:
        p_flags = []
        if protagonist.get("faction"):
            p_flags.append(f"소속: {protagonist['faction']}")
        if protagonist.get("inner_energy_type"):
            p_flags.append(f"내공 유형: {protagonist['inner_energy_type']}")
        if protagonist.get("protagonist_type"):
            p_flags.append(f"주인공 유형: {protagonist['protagonist_type']}")
        if protagonist.get("cultivation_stage"):
            p_flags.append(f"현재 경지: {protagonist['cultivation_stage']}")
        if p_flags:
            flags.append("**주인공 플래그**\n" + "\n".join([f"  - {f}" for f in p_flags]))

    for role_key in ["female_lead", "male_lead", "villain", "mentor"]:
        role = concept_dict.get(role_key, {})
        if role:
            r_flags = []
            label = {"female_lead": "여주", "male_lead": "남주",
                     "villain": "빌런", "mentor": "사부"}.get(role_key, role_key)
            if role.get("faction"):
                r_flags.append(f"소속: {role['faction']}")
            if role.get("cultivation_stage"):
                r_flags.append(f"경지: {role['cultivation_stage']}")
            if role.get("relation_to_protagonist"):
                r_flags.append(f"주인공과의 관계: {role['relation_to_protagonist']}")
            if r_flags:
                flags.append(f"**{label} 플래그**\n" + "\n".join([f"  - {f}" for f in r_flags]))

    if flags:
        return "## 캐릭터 플래그\n\n" + "\n\n".join(flags)
    return ""


