def get_pacing_block(ep, total_eps=50):
    """회차별 페이싱 가이드."""
    stage = ""
    actions = []

    if ep <= 5:
        stage = "오프닝 단계 (1-5화)"
        actions = [
            "5초 훅 필수 (위기·의문·충격)",
            "주인공 욕망·결핍 명확히",
            "세계관 설명은 사건 속에 녹여",
            "1화 말에 강력한 클리프행어",
            "2-3화에 치트키 혹은 특수성 공개",
        ]
    elif ep <= 10:
        stage = "초반 구축 (6-10화)"
        actions = [
            "핵심 조력자 1명 등장",
            "첫 번째 파워업 혹은 소규모 승리",
            "중장기 목표 구체화",
            "라이벌 혹은 적대자 예고",
        ]
    elif ep <= 20:
        stage = "중반 전반 (11-20화)"
        actions = [
            "5화마다 파워업 리듬 유지",
            "10화쯤 주요 캐릭터 전원 등장 완료",
            "첫 번째 대형 전투 혹은 사건",
            "떡밥 배치 집중",
            "페이크 엔딩 가능 (가짜 승리 후 반전)",
        ]
    elif ep <= 30:
        stage = "중반 후반 (21-30화)"
        actions = [
            "중간 보스 격파",
            "정체성 혹은 세계관의 균열",
            "조력자 서사 심화",
            "떡밥 회수 시작",
        ]
    elif ep <= 40:
        stage = "후반 (31-40화)"
        actions = [
            "전생 원수·시스템 정체 등 핵심 진실 공개",
            "최종 빌런 본격 등장",
            "주인공 최대 위기",
            "조력자 희생 혹은 배신",
        ]
    else:
        stage = "종반 (41-50화)"
        actions = [
            "최종 결전 준비",
            "모든 떡밥 회수",
            "Core Arc 마무리",
            "Extension 고리 설계",
            "여운 있는 마지막 장면",
        ]

    actions_text = "\n".join([f"  - {a}" for a in actions])
    return f"""
## 페이싱 ({stage})
현재 {ep}/{total_eps}화
{actions_text}
""".strip()


# ═══════════════════════════════════════════════════
# 클리프행어 9유형
# ═══════════════════════════════════════════════════

CLIFFHANGER_TYPES = [
    "Slap", "Reveal", "Reversal", "Arrival",
    "Choice", "Threat", "Tears", "Challenge", "Breakthrough"
]

CLIFFHANGER_RULES = """[클리프행어 9유형]

1. Slap (뺨) — 예상치 못한 폭력·모욕
   "한 줄기 바람이 스치나 싶은 순간, 그의 뺨에 선명한 손자국이 남았다."

2. Reveal (폭로) — 숨겨진 정체·진실 공개
   "그 목소리였다. 전생에서 그를 죽인 바로 그 목소리."

3. Reversal (역전) — 상황의 극적 뒤집힘
   "승자는 그가 아니었다. 검을 쥔 손이 천천히 무너져 내렸다."

4. Arrival (등장) — 강렬한 인물의 도착
   "문이 열렸다. 그곳에 서 있는 건, 죽었다고 알려진 남자였다."

5. Choice (선택) — 결정적 갈림길
   "둘 중 하나를 택해야 한다. 사부인가, 그녀인가."

6. Threat (위협) — 다가오는 위기 예고
   "내일 정오, 형산 꼭대기에서 기다리겠다. 오지 않으면 그녀가 죽는다."

7. Tears (눈물) — 감정의 폭발
   "처음으로, 그녀가 울었다. 소리도 없이, 무너지듯."

8. Challenge (도전) — 공식적 선전포고 [무협 특화]
   "정삼각 후, 비무대에서. 거절하면 평생 비겁자로 낙인찍힐 것이다."

9. Breakthrough (돌파 직전) — 각성·경지 돌파 직전 [무협 특화]
   "단전 깊은 곳에서, 무언가 꿈틀거리기 시작했다."
"""


