def _is_section_header_line(line, used_keys=None):
    """섹션 제목 행인지 판정하고, 맞으면 섹션 키를 반환.

    기획서 DOCX는 섹션 제목을 표 헤더(| 세계관 | WORLD-BUILDING |)나
    짧은 제목행([별첨] APPENDIX)으로 표기한다. 둘 다 인식한다.

    [v2.4.0 주의 — 하위 제목 오인 방지]
    스토리라인 섹션 안에는 "캐릭터 소개(Characters)" 같은 하위
    제목이 등장한다. 이를 캐릭터 섹션의 재시작으로 오인하면
    스토리라인 본문이 캐릭터 섹션으로 흘러든다. 기획서 섹션은
    한 번씩 순서대로 나오므로, 이미 사용한 키로는 다시 전환하지
    않는다.
    """
    raw = (line or "").strip()
    if not raw or len(raw) > 60:
        return None
    # 표 구분선(| --- | --- |)은 무시
    if set(raw.replace("|", "").replace("-", "").replace(" ", "")) == set():
        return None

    is_table_row = "|" in raw
    # 표 형식이 아닌 제목행은 더 엄격하게 (본문 문장 오인 방지)
    if not is_table_row and len(raw) > 30:
        return None

    probe = raw.replace("|", " ").replace("*", "").replace("#", "")
    probe = probe.replace("[", " ").replace("]", " ").replace("★", " ")
    probe_flat = probe.replace(" ", "").upper()
    if not probe_flat:
        return None

    used = used_keys or set()
    for key, keywords in BRIEF_SECTION_KEYS:
        if key in used:
            continue  # 이미 지나간 섹션 — 하위 제목으로 간주
        for kw in keywords:
            if kw.replace(" ", "").upper() in probe_flat:
                return key
    return None


def extract_brief_sections(brief_text):
    """기획서를 섹션 단위로 분해 (v2.4.0 신규).

    Returns:
        dict {section_key: text}. 어느 섹션에도 속하지 않는 앞부분·
        중간 텍스트는 "other"에 누적한다. 섹션 제목이 전혀 없는
        기획서는 전체가 "other"로 들어간다(안전 폴백).
    """
    sections = {}
    current = "other"
    used = set()
    buf = []

    def _flush():
        if buf:
            chunk = "\n".join(buf).strip()
            if chunk:
                sections[current] = (sections.get(current, "") + "\n\n" + chunk).strip()
        buf.clear()

    for line in (brief_text or "").splitlines():
        hit = _is_section_header_line(line, used)
        if hit:
            _flush()
            current = hit
            used.add(hit)
            continue
        buf.append(line)
    _flush()
    return sections


def compress_brief_for_prompt(brief_text, budget=12000, profile="concept"):
    """섹션 인식 가중 압축 (v2.4.0 신규 — 단순 앞뒤 절단 대체).

    각 섹션에 가중치 비례로 예산을 배분한다. 배분량보다 짧은
    섹션은 전문을 보존하고, 남은 예산은 긴 섹션에 재분배한다.
    최종적으로 예산을 넘는 섹션만 앞·뒤 발췌한다.

    Args:
        brief_text: 기획서 원문
        budget: 프롬프트에 실을 총 글자 예산
        profile: BRIEF_PRIORITY_PROFILES 키 ("concept"/"martial"/"storyline")

    Returns:
        (압축된 텍스트, 리포트 dict)
    """
    text = brief_text or ""
    if len(text) <= budget:
        return text, {"truncated": False, "total": len(text), "sections": {}}

    weights = BRIEF_PRIORITY_PROFILES.get(profile, BRIEF_PRIORITY_PROFILES["concept"])
    sections = extract_brief_sections(text)
    if not sections:
        sections = {"other": text}

    # 1차 배분
    active = {k: v for k, v in sections.items() if v.strip()}
    total_weight = sum(weights.get(k, 0.3) for k in active) or 1.0
    alloc = {k: int(budget * (weights.get(k, 0.3) / total_weight)) for k in active}

    # 짧은 섹션의 잉여 예산을 회수해 재분배
    surplus = 0
    needy = []
    for k, v in active.items():
        if len(v) <= alloc[k]:
            surplus += alloc[k] - len(v)
            alloc[k] = len(v)
        else:
            needy.append(k)
    if needy and surplus > 0:
        needy_weight = sum(weights.get(k, 0.3) for k in needy) or 1.0
        for k in needy:
            alloc[k] += int(surplus * (weights.get(k, 0.3) / needy_weight))

    # 섹션 순서는 기획서 원래 순서를 따른다
    order = [k for k, _ in BRIEF_SECTION_KEYS] + ["other"]
    label = {
        "overview": "개요", "logline": "로그라인", "intent": "기획의도",
        "world": "세계관", "character": "캐릭터", "synopsis": "시놉시스",
        "storyline": "스토리라인", "episodes": "회차 구성",
        "appendix": "별첨(무공·기보·무기)", "direction": "작가 방향",
        "canon": "확정 원고", "devices": "서사 장치", "other": "기타",
    }

    out = []
    report = {}
    for k in order:
        if k not in active:
            continue
        body = active[k].strip()
        cap = max(alloc.get(k, 0), 0)
        if len(body) > cap and cap > 400:
            # 꼬리를 비례 확보한다. 스토리라인·별첨은 뒷부분에
            # 클라이맥스·무기 목록이 오므로 꼬리가 짧으면 소실된다.
            tail_len = max(300, min(1500, cap // 4))
            head = body[: cap - tail_len]
            tail = body[-tail_len:]
            body = head + "\n[...이 섹션 일부 생략...]\n" + tail
            report[k] = {"original": len(active[k]), "kept": len(body), "cut": True}
        elif len(body) > cap:
            body = body[:cap]
            report[k] = {"original": len(active[k]), "kept": len(body), "cut": True}
        else:
            report[k] = {"original": len(active[k]), "kept": len(body), "cut": False}
        out.append(f"===== [{label.get(k, k)}] =====\n{body}")

    return "\n\n".join(out), {
        "truncated": True,
        "total": len(text),
        "profile": profile,
        "sections": report,
    }


def build_world_setting_block(concept_card):
    """작가의 세계관을 집필 단계로 전달하는 블록 (v2.3.1 신규).

    기존에는 컨셉 카드에서 톤·주인공유형·공식·장르만 추출해 쓰고
    world_setting을 버렸다. 그 결과 작가가 설계한 세계관이 본문
    집필에 반영되지 않았다.
    """
    if not isinstance(concept_card, dict):
        return ""
    ws = concept_card.get("world_setting")
    comp = concept_card.get("competition_rules")
    has_comp = isinstance(comp, dict) and any(
        isinstance(v, str) and v.strip() for v in comp.values()
    )
    if not ws and not has_comp:
        return ""

    lines = ["## ⭐ 작품 고유 세계관 (작가 설정 — 임의 변경 금지)"]
    if not ws:
        ws = {}

    if isinstance(ws, str):
        lines.append(ws.strip())
    elif isinstance(ws, dict):
        label_map = {
            "era": "시대·배경",
            "location": "주요 장소",
            "key_factions": "핵심 세력·문파",
            "unique_rules": "이 세계만의 규칙",
            "martial_level_system": "경지·무공 등급 체계",
            "power_system": "무공 체계",
            "social_structure": "사회 구조",
        }
        # v2.4.0: factions는 구조체 배열이므로 따로 렌더한다
        facs = ws.get("factions")
        if isinstance(facs, list) and facs:
            lines.append("")
            lines.append("### 문파·학원 설정 (작가 설정)")
            for f in facs[:8]:
                if not isinstance(f, dict):
                    continue
                nm = (f.get("name") or "").strip()
                if not nm:
                    continue
                bits = []
                for k, lb in (("location", "위치"), ("signature_art", "대표 무공"),
                              ("training", "수련법"), ("culture", "문화"),
                              ("history", "내력")):
                    v = f.get(k)
                    if isinstance(v, str) and v.strip():
                        bits.append(f"{lb}: {v.strip()}")
                mem = f.get("key_members")
                if isinstance(mem, list) and mem:
                    bits.append("주요 인물: " + ", ".join(str(m) for m in mem[:5]))
                lines.append(f"- **{nm}**" + (f" — {' / '.join(bits)}" if bits else ""))
        for key, val in ws.items():
            if not val:
                continue
            label = label_map.get(key, key)
            if isinstance(val, (list, tuple)):
                val_txt = " / ".join(str(v) for v in val)
            elif isinstance(val, dict):
                val_txt = " / ".join(f"{k}: {v}" for k, v in val.items())
            else:
                val_txt = str(val)
            lines.append(f"- **{label}**: {val_txt}")

    # v2.4.0: 대회 규칙 (학원 무협·대회 모티프 작품의 핵심 룰)
    if has_comp:
        lines.append("")
        lines.append("### 대회 규칙 (작가 설정 — 판정 방식 변경 금지)")
        for k, lb in (("name", "대회명"), ("format", "형식"),
                      ("scoring", "판정"), ("disqualification", "실격"),
                      ("prize", "상금")):
            v = comp.get(k)
            if isinstance(v, str) and v.strip():
                lines.append(f"- {lb}: {v.strip()}")

    # 세계관 준수 지시
    lines.append("")
    lines.append("### 세계관 준수 규칙")
    lines.append("- 위 설정은 작가가 확정한 것이다. 새 세력·새 규칙을 임의로 만들지 말 것.")
    lines.append("- 경지·등급 체계는 위 정의를 그대로 사용. 다른 이름으로 바꾸지 말 것.")
    lines.append("- 이 세계만의 규칙이 회차 안에서 최소 1회 구체적으로 작동해야 한다.")
    lines.append("  (설정을 배경으로만 두지 말고, 사건에 개입시킬 것)")

    return "\n".join(lines)


def build_martial_bible_prompt(brief_text, concept_card=None):
    """기획서 → 초식 바이블 추출 (v2.4.0 신규).

    [왜 필요한가]
    무협 기획서의 별첨(무공의 종류·기보·무기)은 작가가 설계한
    핵심 자산이다. 그러나 v2.3.1까지 컨셉 카드 스키마에는 이를
    담을 필드가 없어 전량 소실됐고, 그 결과 집필 단계에서 LLM이
    무협 관용 초식명(자하신공·태극혼원공 등)을 창작해 넣었다.

    이 함수는 별첨·세계관을 우선 확보한 압축 텍스트에서
    초식 바이블을 추출한다. 창작은 금지다 — 없으면 빈 배열이다.
    """
    compressed, _report = compress_brief_for_prompt(
        brief_text, budget=14000, profile="martial"
    )

    card_hint = ""
    if isinstance(concept_card, dict) and concept_card:
        keys = ["title", "logline", "genre", "formula_key", "wuxia_formula_main"]
        picked = {k: concept_card.get(k) for k in keys if concept_card.get(k)}
        if picked:
            card_hint = (
                "\n[이미 확정된 컨셉 카드 정보 — 참고용]\n"
                + json.dumps(picked, ensure_ascii=False, indent=2) + "\n"
            )

    return f"""다음은 무협 작품 기획서입니다. 여기서 **무공·초식·기보·무기 설정만**
추출해 초식 바이블 JSON으로 정리하세요.

[기획서 (섹션별 발췌 — 별첨 우선 보존)]
{compressed}
{card_hint}
[추출 지침 — 반드시 지킬 것]
1. **기획서에 적힌 것만 추출한다.** 없는 무공·초식·기보를 창작하지 않는다.
   해당 항목이 없으면 빈 배열([]) 또는 빈 문자열("")로 둔다.
2. **고유명사는 원문 철자를 그대로 옮긴다.** 한자 병기가 있으면 함께 옮긴다.
   예: 화산장풍(花山掌風), 당랑연검술(螳螂軟劍術), 아미자(阿美刺)
   무협 관용 명칭으로 바꾸지 않는다. 작가가 일부러 다른 한자를 쓴
   경우가 있으므로(華山 → 花山 등) 원문을 존중한다.
3. 기획서에 설명이 있는 항목만 4요소(원리·시각·대가)를 채운다.
   설명이 없으면 그 필드만 빈 문자열로 두고 이름은 살린다.
4. 경지·등급 체계가 기획서에 없으면 martial_level_system을 빈
   문자열로 둔다. **경지 체계를 임의로 만들어 넣지 않는다.**
   (내공/외공 분류로 강약을 표현하는 작품도 있다.)
5. author_locked_terms에는 본문 집필 시 철자를 바꾸면 안 되는
   고유명사를 모두 모은다 — 문파·학교·초식·무기·기보 이름.

[JSON 출력 — 이 구조만. 마크다운·설명·주석 절대 금지]
{{
  "martial_level_system": "",
  "power_taxonomy": [
    {{
      "name": "",
      "category": "내공 / 외공 / 경공 / 금기 / 기타 중 하나",
      "principle": "",
      "visual": "",
      "cost": ""
    }}
  ],
  "faction_arts": [
    {{
      "faction": "",
      "signature": "",
      "training": "",
      "arts": [
        {{
          "name": "",
          "tier": "",
          "principle": "",
          "visual": "",
          "cost": "",
          "users": [],
          "first_appearance_hint": ""
        }}
      ]
    }}
  ],
  "artifacts": [
    {{
      "name": "",
      "type": "비급 / 영물 / 무기 / 영약 / 독약 / 향 중 하나",
      "owner": "",
      "power": "",
      "visual": "",
      "cost": "",
      "reveal_timing": ""
    }}
  ],
  "weapons": [
    {{ "name": "", "faction": "", "form": "", "visual": "" }}
  ],
  "forbidden": [
    {{ "name": "", "trigger": "", "consequence": "" }}
  ],
  "competition_rules": {{
    "name": "",
    "format": "",
    "scoring": "",
    "disqualification": "",
    "prize": ""
  }},
  "author_locked_terms": []
}}

[중요]
- 위 JSON 객체만 출력. 코드 블록(```) 없이.
- 빈값은 "" 또는 []. null 금지.
- "등에서 선택" 같은 가이드 문구를 출력값에 넣지 말 것."""


def build_storyline_extract_prompt(brief_text, concept_card=None):
    """기획서 → 막 구조 스토리라인 추출 (v2.4.0 신규).

    [왜 필요한가]
    아미고 기획서의 스토리라인 8,300자에는 EP1 오프닝(표창 기습·
    쇠구슬·축지법 등교)과 결승의 정체 폭로가 설계돼 있었다.
    12,000자 앞뒤 절단에서 이 구간이 통째로 잘려나가 EP1이
    백지 상태로 집필됐다. 이 함수는 스토리라인을 우선 확보한
    압축으로 막 구조를 보존한다. Core Arc 설계의 재료가 된다.
    """
    compressed, _report = compress_brief_for_prompt(
        brief_text, budget=12000, profile="storyline"
    )

    title = ""
    if isinstance(concept_card, dict):
        title = concept_card.get("title", "") or ""

    return f"""다음은 무협 작품 기획서입니다. 여기서 **막 구조 스토리라인만**
추출해 JSON으로 정리하세요. {f"작품명: {title}" if title else ""}

[기획서 (섹션별 발췌 — 스토리라인·시놉시스 우선 보존)]
{compressed}

[추출 지침]
1. 기획서에 서술된 사건만 옮긴다. 없는 사건을 창작하지 않는다.
2. 기획서가 이미 막·단계 이름을 쓰고 있으면 **그 이름을 그대로**
   beat_name에 옮긴다. (예: 오프닝, 후킹포인트, 도발적 사건,
   첫번째 변곡점, 중간점의 사건, 두번째 변곡점, 클라이맥스, 결말)
3. 각 비트의 events에는 실제로 벌어지는 사건을 순서대로 적는다.
   인물 이름·초식명·소품 이름은 원문 철자를 그대로 쓴다.
4. opening_scene은 기획서 오프닝 장면을 최대한 구체적으로 옮긴다.
   EP1 집필의 직접 재료가 되므로 시각적 디테일(무엇이 날아오는가,
   누가 무슨 무공을 쓰는가)을 빠뜨리지 않는다.
5. season_boundary에는 이 시즌이 어디서 끝나고 다음 시즌으로
   무엇이 넘어가는지 적는다. 기획서에 없으면 빈 문자열.

[JSON 출력 — 이 구조만. 마크다운·설명·주석 절대 금지]
{{
  "opening_scene": {{
    "setting": "",
    "events": [],
    "martial_showcase": "",
    "hook": ""
  }},
  "acts": [
    {{
      "act": "1막 / 2막 / 3막",
      "beats": [
        {{
          "beat_name": "",
          "events": [],
          "characters": [],
          "martial_showcase": "",
          "turning_point": ""
        }}
      ]
    }}
  ],
  "season_boundary": "",
  "unresolved_threads": []
}}

[중요]
- 위 JSON 객체만 출력. 코드 블록(```) 없이.
- 빈값은 "" 또는 []. null 금지."""


# ═══════════════════════════════════════════════════
# 무공 대전 (Martial Codex) — v2.7.0 신규
#
# [왜 필요한가]
# 기획서 1회 추출로 확정된 바이블은 50화를 버티지 못한다.
# 실측: 작가 원고 EP1에서 8종, EP2에서 4종이 바이블 밖에서 태어났다.
# 2화에 12종이면 50화는 200~300종 규모다.
#
# 무공 대전은 두 가지를 동시에 해결한다.
#   ① 집필 재료 — A29 쿼터(회차당 5종)를 50화 내내 회전시킬 사전
#   ② 별첨 문서 — 원고 완료 후 작품 제안서에 첨부하는 완성 설정집
# 그래서 항목 스키마가 집필용 4필드가 아니라 문서용 13필드다.
# ═══════════════════════════════════════════════════

# 4등급 정원제 — 등급별 문파당 상한.
# 정원을 두는 이유: 사전이 무제한 팽창하면 프롬프트를 잡아먹고,
# 독자도 초식을 따라오지 못한다. 무공의 무게는 희소성에서 나온다.
MARTIAL_CODEX_TIERS = {
    "비전": {
        "hanja": "祕傳",
        "quota_per_faction": 2,
        "desc": "문파 최고 절기. 장문인·계승자만 전수받는다. 작중 1~2회 시전이 적정.",
        "guide": "이름만 알려져 있고 실체는 베일에 싸인 무공. 시전 자체가 사건이 된다.",
    },
    "절기": {
        "hanja": "絕技",
        "quota_per_faction": 4,
        "desc": "문파 대표 무공. 그 문파를 상징한다. 상급생·교사가 쓴다.",
        "guide": "독자가 문파 이름과 함께 기억하는 무공. 회차의 볼거리를 담당한다.",
    },
    "중급": {
        "hanja": "中級",
        "quota_per_faction": 5,
        "desc": "제자 수련 과정의 실전 무공. 대련·시합의 주력.",
        "guide": "가장 자주 등장한다. A29 쿼터를 실질적으로 채우는 층이다.",
    },
    "기초": {
        "hanja": "基礎",
        "quota_per_faction": 3,
        "desc": "입문 단계. 신입생이 배운다. 경공·운기·기본 보법 계열.",
        "guide": "주인공의 성장 출발점. 후반부에 응용되어 재등장하면 좋다.",
    },
}

# 별첨 제출용 항목 필드 (13) — 이 순서가 문서 표의 열 순서다.
MARTIAL_CODEX_ENTRY_FIELDS = [
    ("name", "무공명(한자 병기)"),
    ("name_en", "영문 표기"),
    ("faction", "문파·계보"),
    ("tier", "등급"),
    ("category", "분류"),
    ("lineage", "전승 계보"),
    ("principle", "원리"),
    ("visual", "시연 이미지"),
    ("strength", "강점"),
    ("cost", "대가·한계"),
    ("counter", "상성"),
    ("acquisition", "습득 조건"),
    ("planned_episodes", "등장 예정 회차"),
]


def build_martial_codex_expansion_prompt(martial_bible, concept_card,
                                         faction, target_count=12,
                                         existing_names=None,
                                         storyline_acts=None):
    """무공 대전 확장 — 문파 단위 배치 생성 (v2.7.0 신규).

    [왜 문파 단위인가]
    60종을 한 번에 생성하면 응답이 토큰 한도에서 잘려 JSON 파싱이
    실패한다 (사고 패턴 A·C). 문파당 12종 × 5문파로 나누면
    1회 출력이 3,000자 내외로 안정권에 들어온다.

    Args:
        martial_bible: 현재 바이블 (기존 자산 — 중복 방지 기준)
        concept_card: 컨셉 카드 (톤·공식·세계관 참조)
        faction: 확장 대상 문파명 (예: "무당파")
        target_count: 생성 목표 종수 (표준 12)
        existing_names: 이미 등재된 무공명 리스트 (중복 금지 목록)
        storyline_acts: 막 구조 (등장 예정 회차 배정 참고)

    Returns:
        프롬프트 문자열. 응답은 {"arts": [...]} 형태의 JSON.
    """
    existing_names = existing_names or []

    # 컨셉 카드에서 필요한 최소 정보만 뽑는다 (토큰 절약)
    card_keys = [
        "title", "logline", "genre", "formula_key", "wuxia_formula_main",
        "protagonist_type", "tone_preset", "world_setting", "era_setting",
    ]
    card = {}
    if isinstance(concept_card, dict):
        card = {k: concept_card.get(k) for k in card_keys if concept_card.get(k)}

    mls = ""
    fac_info = ""
    if isinstance(martial_bible, dict):
        mls = (martial_bible.get("martial_level_system") or "").strip()
        for grp in martial_bible.get("faction_arts") or []:
            if not isinstance(grp, dict):
                continue
            if str(grp.get("faction", "")).strip().startswith(faction[:3]):
                bits = []
                for k, lb in (("signature", "대표 무공"), ("training", "수련 방식")):
                    if grp.get(k):
                        bits.append(f"{lb}: {str(grp[k]).strip()}")
                fac_info = " / ".join(bits)
                break

    tier_lines = []
    for tier, meta in MARTIAL_CODEX_TIERS.items():
        tier_lines.append(
            f"- **{tier}({meta['hanja']})** {meta['quota_per_faction']}종 — "
            f"{meta['desc']}\n    {meta['guide']}"
        )
    tier_block = "\n".join(tier_lines)

    ban_block = ""
    if existing_names:
        ban_block = (
            "\n[이미 등재된 무공 — 같은 이름·유사 이름 생성 절대 금지]\n"
            + ", ".join(str(n) for n in existing_names[:120]) + "\n"
        )

    story_hint = ""
    if isinstance(storyline_acts, dict) and storyline_acts.get("acts"):
        beats = []
        for act in (storyline_acts.get("acts") or [])[:4]:
            if isinstance(act, dict) and act.get("act"):
                beats.append(str(act["act"]).strip())
        if beats:
            story_hint = (
                "\n[막 구조 — 등장 예정 회차 배정 참고]\n"
                + " / ".join(beats) + "\n"
            )

    return f"""당신은 무협 세계관 설계자입니다. 아래 작품의 **{faction}** 무공 체계를
확장해 무공 대전(Martial Codex) 항목 {target_count}종을 설계하세요.

[작품 정보]
{json.dumps(card, ensure_ascii=False, indent=2)}

[확장 대상 문파]
{faction}
{("기존 설정: " + fac_info) if fac_info else "기존 설정 없음 — 새로 설계"}

[작품의 경지·등급 체계]
{mls if mls else "미정 — 아래 4등급 체계를 사용할 것"}

[등급 정원 — 반드시 이 배분을 지킬 것]
{tier_block}
{ban_block}{story_hint}
[설계 원칙 — 이 작품의 자산을 만드는 일입니다]
1. **무협 관용명 절대 금지.** 자하신공·태극혼원공·구양신공·매화검법·
   항룡십팔장·능파미보·일양지·육맥신검·건곤대나이 등 기존 무협 작품의
   무공명을 쓰지 않습니다. 전부 이 작품 고유의 창작이어야 합니다.
2. **문파 성격의 일관성.** 한 문파의 무공은 같은 철학을 공유합니다.
   유(柔)의 문파에 폭발형 장법을 섞지 않습니다. 12종이 하나의 계보로
   읽혀야 합니다.
3. **작가 철자 존중.** 기존 바이블의 한자를 그대로 씁니다. 작가가
   일부러 다른 한자를 쓴 경우가 있습니다 (華山 → 花山 등).
   기존 문파명의 한자를 임의로 교정하지 않습니다.
4. **원리(principle)는 자연·사물의 이치로 씁니다.** 이 필드가
   집필 시 A30 ③해설의 재료가 됩니다. 추상어("강력한 기운")가 아니라
   무엇을 모방했고 무엇을 이용하는지 씁니다.
   (좋은 예) 사마귀의 앞발 관절 구조를 연검에 옮겨, 상대의 힘을
   흘려보낸 뒤 관절의 반동으로 되돌려준다.
5. **대가(cost)는 반드시 있습니다.** 대가 없는 무공은 서사에서
   쓸 수 없습니다. 내공 소모·후유증·시전 조건·통하지 않는 상대 중
   최소 하나를 구체적으로 씁니다.
6. **상성(counter)을 설계합니다.** 어떤 무공에 강하고 어떤 무공에
   약한지 씁니다. 이게 있으면 대결 구도를 짜기 쉬워집니다.
7. **영문 표기(name_en)는 3어절 이내**로 만듭니다. 라인웹툰 영문
   동시 출시 시 그대로 쓰입니다. 음역이 아니라 의미 번역을 우선합니다.
   (좋은 예) 청수유수권 → Clearwater Flowing Fist
8. **한자 병기는 이름에만** 씁니다. 설명 필드에는 한자를 넣지 않습니다.
9. 등장 예정 회차(planned_episodes)는 등급에 맞춰 배정합니다.
   기초는 1~10화, 중급은 5~35화, 절기는 15~45화, 비전은 35~50화 범위가
   기본입니다. 정확한 회차가 아니라 "EP12~18" 같은 구간으로 씁니다.

[JSON 출력 — 이 구조만. 마크다운·설명·주석 절대 금지]
{{
  "faction": "{faction}",
  "faction_philosophy": "이 문파 무공의 공통 철학 한 문장",
  "arts": [
    {{
      "name": "무공명(한자)",
      "name_en": "",
      "faction": "{faction}",
      "tier": "비전 / 절기 / 중급 / 기초 중 하나",
      "category": "내공 / 외공 / 경공 / 검법 / 도법 / 장법 / 권법 / 창법 / 보법 / 진법 / 금기 중 하나",
      "lineage": "전승 계보 — 누가 창안하고 누가 잇는가",
      "principle": "",
      "visual": "",
      "strength": "",
      "cost": "",
      "counter": "",
      "acquisition": "습득 조건 — 무엇을 갖춰야 배울 수 있는가",
      "planned_episodes": "EP00~00",
      "users": []
    }}
  ]
}}

정확히 {target_count}종을 생성하고, 등급 정원(비전 2 / 절기 4 / 중급 5 / 기초 3)을
지키세요."""


def build_martial_bible_block(martial_bible):
    """초식 바이블을 플롯·집필·재집필 프롬프트에 주입 (v2.4.0 신규).

    [v2.7.0 배선 구멍 마감 — 사고 패턴 L]
    faction_arts의 principle(원리)을 전달하지 않고 visual·cost·users만
    보내고 있었다. principle은 A30 ③해설의 핵심 재료다. 스키마에는
    있는데 읽는 쪽이 없어 3박자 완주 0회의 직접 원인이 됐다.
    v2.7.0에서 principle·tier·lineage·strength를 함께 싣는다.
    """
    if not isinstance(martial_bible, dict) or not martial_bible:
        return ""

    lines = ["## ⚔️ 초식 바이블 (작가 설정 — 철자 변경 금지)"]

    mls = (martial_bible.get("martial_level_system") or "").strip()
    if mls:
        lines.append("")
        lines.append(f"**경지·등급 체계**: {mls}")

    tax = martial_bible.get("power_taxonomy") or []
    if isinstance(tax, list) and tax:
        lines.append("")
        lines.append("### 무공 분류")
        for item in tax[:14]:
            if not isinstance(item, dict):
                continue
            nm = (item.get("name") or "").strip()
            if not nm:
                continue
            cat = (item.get("category") or "").strip()
            desc = (item.get("principle") or item.get("visual") or "").strip()
            head = f"- **{nm}**" + (f" [{cat}]" if cat else "")
            lines.append(head + (f" — {desc}" if desc else ""))

    fa = martial_bible.get("faction_arts") or []
    if isinstance(fa, list) and fa:
        lines.append("")
        lines.append("### 유파·학교별 초식")
        for grp in fa[:8]:
            if not isinstance(grp, dict):
                continue
            fac = (grp.get("faction") or "").strip()
            if not fac:
                continue
            sig = (grp.get("signature") or "").strip()
            lines.append(f"**{fac}**" + (f" — {sig}" if sig else ""))
            for art in (grp.get("arts") or [])[:12]:
                if not isinstance(art, dict):
                    continue
                nm = (art.get("name") or "").strip()
                if not nm:
                    continue
                tier = (art.get("tier") or "").strip()
                head = f"  · {nm}" + (f" [{tier}]" if tier else "")
                bits = []
                # v2.7.0: principle(원리)을 반드시 싣는다.
                #   A30 ③해설의 핵심 재료다. v2.6.0까지 스키마에는 있으나
                #   이 블록이 전달하지 않아 3박자 완주 0회의 원인이 됐다.
                if art.get("principle"):
                    bits.append("원리: " + str(art["principle"]).strip()[:120])
                if art.get("visual"):
                    bits.append("시연: " + str(art["visual"]).strip()[:100])
                if art.get("strength"):
                    bits.append("강점: " + str(art["strength"]).strip()[:80])
                if art.get("cost"):
                    bits.append("대가: " + str(art["cost"]).strip()[:80])
                if art.get("lineage"):
                    bits.append("계보: " + str(art["lineage"]).strip()[:60])
                users = art.get("users") or []
                if isinstance(users, list) and users:
                    bits.append("사용자: " + ", ".join(str(u) for u in users[:4]))
                lines.append(head)
                for b in bits:
                    lines.append(f"      {b}")

    arts = martial_bible.get("artifacts") or []
    if isinstance(arts, list) and arts:
        lines.append("")
        lines.append("### 기보·영물")
        for it in arts[:10]:
            if not isinstance(it, dict):
                continue
            nm = (it.get("name") or "").strip()
            if not nm:
                continue
            bits = []
            if it.get("owner"):
                bits.append("소유: " + str(it["owner"]).strip())
            if it.get("power"):
                bits.append(str(it["power"]).strip())
            if it.get("reveal_timing"):
                bits.append("공개 시점: " + str(it["reveal_timing"]).strip())
            lines.append(f"- **{nm}**" + (f" — {' / '.join(bits)}" if bits else ""))

    wps = martial_bible.get("weapons") or []
    if isinstance(wps, list) and wps:
        lines.append("")
        lines.append("### 무기")
        for it in wps[:10]:
            if not isinstance(it, dict):
                continue
            nm = (it.get("name") or "").strip()
            if not nm:
                continue
            extra = " / ".join(
                str(it[k]).strip() for k in ("faction", "form", "visual")
                if it.get(k)
            )
            lines.append(f"- **{nm}**" + (f" — {extra}" if extra else ""))

    fb = martial_bible.get("forbidden") or []
    if isinstance(fb, list) and fb:
        lines.append("")
        lines.append("### 금기·부작용")
        for it in fb[:8]:
            if not isinstance(it, dict):
                continue
            nm = (it.get("name") or "").strip()
            if not nm:
                continue
            tail = " / ".join(
                str(it[k]).strip() for k in ("trigger", "consequence") if it.get(k)
            )
            lines.append(f"- **{nm}**" + (f" — {tail}" if tail else ""))

    cr = martial_bible.get("competition_rules")
    if isinstance(cr, dict) and any((cr.get(k) or "") for k in cr):
        lines.append("")
        lines.append("### 대회 규칙")
        cr_label = {
            "name": "대회명", "format": "형식", "scoring": "판정",
            "disqualification": "실격", "prize": "상금",
        }
        for k, lb in cr_label.items():
            v = (cr.get(k) or "").strip() if isinstance(cr.get(k), str) else ""
            if v:
                lines.append(f"- {lb}: {v}")

    locked = martial_bible.get("author_locked_terms") or []
    if isinstance(locked, list) and locked:
        terms = [str(t).strip() for t in locked if str(t).strip()][:40]
        if terms:
            lines.append("")
            lines.append("### A28 철자 고정 목록 (변경 금지)")
            lines.append(", ".join(terms))

    if len(lines) <= 1:
        return ""

    lines.append("")
    lines.append("### 운용 규칙 (A28)")
    lines.append("- 위 목록의 고유명사는 **철자·한자를 그대로** 쓴다. 유사어로 바꾸지 않는다.")
    lines.append("- 목록에 **없는 초식을 새로 만들지 않는다.** 서사상 반드시 필요하면")
    lines.append("  A27의 4요소 설명을 붙여 도입하고, 이후 회차에서 같은 이름으로 고정한다.")
    lines.append("- 무협 관용 초식명(자하신공·태극혼원공 등)으로 대체 금지.")
    return "\n".join(lines)


def build_storyline_block(storyline_acts, ep_number=None, total_eps=50):
    """기획서 막 구조 스토리라인을 설계·집필에 주입 (v2.4.0 신규).

    Args:
        storyline_acts: build_storyline_extract_prompt 산출물
        ep_number: 회차 번호. 1~2화면 오프닝 장면을 전면에 세운다.
        total_eps: 총 회차 수 (막 위치 안내용)
    """
    if not isinstance(storyline_acts, dict) or not storyline_acts:
        return ""

    lines = ["## 📖 기획서 스토리라인 (작가 설계 — 이 흐름을 따를 것)"]

    op = storyline_acts.get("opening_scene")
    if isinstance(op, dict) and (op.get("events") or op.get("setting")):
        is_opening_ep = ep_number is None or int(ep_number) <= 2
        head = "### ⭐ 오프닝 장면 (작가 설계 — EP1의 직접 재료)" if is_opening_ep \
            else "### 오프닝 장면 (참고 — 이미 지난 구간)"
        lines.append("")
        lines.append(head)
        if op.get("setting"):
            lines.append(f"- 배경: {str(op['setting']).strip()}")
        for ev in (op.get("events") or [])[:8]:
            lines.append(f"- {str(ev).strip()}")
        if op.get("martial_showcase"):
            lines.append(f"- 무공 시전: {str(op['martial_showcase']).strip()}")
        if op.get("hook"):
            lines.append(f"- 후킹: {str(op['hook']).strip()}")

    acts = storyline_acts.get("acts")
    if isinstance(acts, list) and acts:
        lines.append("")
        lines.append("### 막 구조")
        for act in acts[:4]:
            if not isinstance(act, dict):
                continue
            nm = (act.get("act") or "").strip()
            if nm:
                lines.append(f"**{nm}**")
            for beat in (act.get("beats") or [])[:10]:
                if not isinstance(beat, dict):
                    continue
                bn = (beat.get("beat_name") or "").strip()
                evs = beat.get("events") or []
                ev_txt = " / ".join(str(e).strip() for e in evs[:3])
                row = f"  · {bn}" if bn else "  ·"
                if ev_txt:
                    row += f" — {ev_txt}"
                lines.append(row)
                if beat.get("martial_showcase"):
                    lines.append(f"      무공: {str(beat['martial_showcase']).strip()}")

    sb = (storyline_acts.get("season_boundary") or "").strip()
    if sb:
        lines.append("")
        lines.append(f"### 시즌 경계\n{sb}")

    ut = storyline_acts.get("unresolved_threads") or []
    if isinstance(ut, list) and ut:
        lines.append("")
        lines.append("### 다음 시즌으로 넘기는 미해결")
        for t in ut[:6]:
            lines.append(f"- {str(t).strip()}")

    if len(lines) <= 1:
        return ""

    lines.append("")
    lines.append("### 스토리라인 준수 규칙")
    lines.append("- 위 흐름은 작가가 설계한 것이다. 사건 순서를 임의로 바꾸지 말 것.")
    lines.append("- 시즌 경계를 넘지 말 것. 다음 시즌 사건을 이 시즌에 끌어오지 않는다.")
    lines.append("- 오프닝 장면이 명시돼 있으면 EP1은 그 장면에서 시작한다.")
    return "\n".join(lines)


def build_martial_registry_block(character_bible, episode_plots=None,
                                 current_ep=1, martial_bible=None):
    """무공·초식 사전 블록 (v2.3.1 신규).

    회차가 진행되면서 등장한 초식을 누적해 집필 프롬프트에 전달한다.
    목적:
      1) 초식 이름 일관성 — 같은 무공이 회차마다 다른 이름으로 나오는 것 방지
      2) 설명 중복 방지 — 이미 설명한 초식을 매번 재설명하지 않게
      3) 신규 초식 첫 등장 시 설명 의무 명시

    Args:
        character_bible: 캐릭터 바이블 (martial_system 필드 사용)
        episode_plots: {ep: plot_dict} — 플롯의 martial_showcase 누적
        current_ep: 현재 집필 회차 (이전 회차만 '기등장'으로 취급)
    """
    # v2.4.0: 초식 바이블이 있으면 그것이 1순위 소스다.
    # (v2.3.1은 character_bible의 martial_system 필드를 읽었으나,
    #  캐릭터 바이블 생성 프롬프트가 그 필드를 요구하지 않아
    #  항상 빈 구역이었다 — 사고 패턴 L)
    mb_block = build_martial_bible_block(martial_bible)

    lines = ["## ⭐ 무공·초식 사전 (일관성 필수)"]
    if mb_block:
        lines = [mb_block, "", "## ⭐ 무공·초식 사전 (회차 누적)"]

    # 1) 바이블에 정의된 인물별 무공 체계
    bible_entries = []
    if isinstance(character_bible, dict):
        def _walk(node):
            if isinstance(node, dict):
                nm = str(node.get("name", "")).split("(")[0].strip()
                ms = node.get("martial_system")
                if nm and ms:
                    ms_txt = ms if isinstance(ms, str) else str(ms)
                    bible_entries.append(f"- **{nm}**: {ms_txt}")
                for v in node.values():
                    _walk(v)
            elif isinstance(node, list):
                for v in node:
                    _walk(v)
        _walk(character_bible)

    if bible_entries:
        lines.append("")
        lines.append("### 인물별 무공 체계 (바이블 확정)")
        lines.extend(bible_entries[:12])

    # 2) 이전 회차에서 이미 등장한 초식 (플롯의 martial_showcase 누적)
    shown = []
    if isinstance(episode_plots, dict):
        for ep_key, plot in episode_plots.items():
            try:
                ep_no = int(ep_key)
            except (TypeError, ValueError):
                continue
            if ep_no >= int(current_ep):
                continue
            if not isinstance(plot, dict):
                continue
            mv = plot.get("martial_showcase")
            if mv and isinstance(mv, str) and mv.strip():
                shown.append((ep_no, mv.strip()))
    shown.sort()

    if shown:
        lines.append("")
        lines.append("### 이미 등장한 초식 (이름을 그대로 사용할 것)")
        for ep_no, mv in shown[-15:]:
            lines.append(f"- EP{ep_no}: {mv}")

    # 3) 운용 규칙
    lines.append("")
    lines.append("### 초식 운용 규칙 (A27)")
    lines.append("- 위 목록에 있는 초식은 **이름을 바꾸지 말 것**. 같은 무공은 같은 이름으로.")
    lines.append("- 이미 설명한 초식은 재설명하지 말 것. 이름 + 효과만 짧게.")
    lines.append("- **신규 초식을 처음 쓸 때는 반드시 설명한다**:")
    lines.append("  · 초식 이름 (한자 3~5자 간결, 첫 등장만 한자 병기)")
    lines.append("  · 어떤 원리·계보의 무공인가 (1~2문장)")
    lines.append("  · 시각적으로 어떻게 보이는가 (2~3문장)")
    lines.append("  · 대가·한계가 있는가 (있으면 1문장)")
    lines.append("- 이번 회차에 새로 만든 초식은 다음 회차부터 위 목록처럼 고정된다.")
    lines.append("  즉흥적으로 만들고 잊지 말 것.")

    return "\n".join(lines)


def _youth_plot_directive(concept_card):
    """1020 타깃 공식일 때만 붙는 플롯 설계 지시."""
    if not is_youth_target(concept_card):
        return ""
    return """## ⭐ 1020 타깃 플롯 설계 지시 (A25·A26)
- 씬마다 대사 주고받기가 실제로 발생하도록 설계할 것.
  인물이 관찰만 하는 씬은 만들지 말 것.
- 무공 시전 씬을 최소 1개 배치 (martial_showcase 필드 필수 기입)
- 사이다 지점을 명시 (catharsis_point) — 주인공의 행동이
  결과를 만들어야 한다. 적이 스스로 물러나는 해결 금지.
- 경쾌·유머 담당 인물의 기능 지점 배치 (humor_beat)
- 클리프행어는 주인공 축, 가능하면 대결 예고형
"""


def _youth_write_directive(concept_card):
    """1020 타깃 공식일 때만 붙는 집필 지시 (A25 정량 기준)."""
    if not is_youth_target(concept_card):
        return ""
    return """- ⭐ 1020 타깃 정량 기준 (A25) — 아래는 권고가 아니라 하한선
  · 대사 글자 비율 30% 이상
  · 주인공 대사 12마디 이상
  · 관찰·묘사 문단 3개 연속 금지 (대사·행동을 끼울 것)
  · 경쾌·유머 담당 인물 기능 수행 2회 이상
- ⭐ 무협 액기스 (A26) — 초식명 명시 무공 시전 1회 이상,
  무기 격돌 또는 타격 1회 이상, 경지·내공 노출 1회 이상
"""


