def get_reader_persona_block(persona_key):
    """독자 페르소나 블록 생성."""
    if not persona_key or persona_key not in READER_PERSONAS:
        return ""
    p = READER_PERSONAS[persona_key]
    value_text = "\n".join([f"  - {v}" for v in p["value_most"]])
    hate_text = "\n".join([f"  - {v}" for v in p["hate_most"]])
    return f"""
## 타깃 독자: {p['label']}
플랫폼: {p['platform_pref']}
읽기 습관: {p['reading_habit']}

[중시하는 것]
{value_text}

[싫어하는 것]
{hate_text}
""".strip()


