def detect_genre_key(genre_input):
    """입력 텍스트에서 장르 키 감지."""
    if not genre_input:
        return "무협"
    g = genre_input.lower()
    if any(k in g for k in ["회귀", "전생", "빙의", "시스템", "이세계", "환생"]):
        return "판타지_무협"
    if any(k in g for k in ["여성향", "여주", "로맨스"]):
        return "여성향_무협"
    return "무협"


def get_genre_rules_block(genre_key):
    """장르 규칙 블록."""
    g = GENRE_RULES.get(genre_key)
    if not g:
        return ""
    return f"{g['rules']}\n\n톤: {g['tone']}\n페이싱: {g['pacing']}"


