RATING_CONVERSION_RULES = """[19금 → 15금 변환 규칙 — 무협 특화]

## 폭력·전투 묘사
- 19금: 참수·해부·유혈 상세 묘사 가능
  예: "검이 목을 지나가자, 머리가 굴러떨어졌다. 피가 분수처럼 솟았다."
- 15금: 치명상은 암시로, 혈흔 제한
  예: "검이 허공을 가르자, 그는 더 이상 움직이지 않았다."

## 관능·정사 장면
- 19금: 신체 접촉·감각 상세 허용
- 15금: 키스·포옹까지. 정사는 장면 전환으로 생략 ("다음 날 아침, 그녀는 그의 품에서 깨어났다")

## 주화입마·고문
- 19금: 신체 파괴 과정 구체적 묘사
- 15금: 결과·감정 중심. 과정은 짧게.

## 욕설·비속어
- 19금: 맥락상 자연스럽게 사용
- 15금: 완화 ("망할", "젠장" 수준까지)

## 원칙
- 15금 변환은 생명력과 긴장을 잃지 않도록
- 단순 삭제가 아니라 대체 장면 제공
- 분량은 동등하게 유지
"""


