# ═══════════════════════════════════════════════════

AI_ANTI_PATTERN = """[AI 문체 탈출 규칙 — 무협 A1~A33]

※ A29~A31(장르 밀도)은 최우선 룰이다. 다른 절제 룰과 충돌하면
   A29~A31을 따른다. 절제는 장르 신호를 줄이는 근거가 아니다.

## 범용 규칙 (A1~A14)
A1. "모든"·"마침내"·"절대로" 남발 금지
A2. 3음절 이상 형용사 반복 금지 ("강력한", "아름다운")
A3. 인과관계를 항상 설명하지 말 것. 독자가 추론하게.
A4. 대사마다 감정 설명 붙이지 말 것 ("그녀가 슬프게 말했다")
A5. 감각 디테일 없는 추상 묘사 금지
A6. "왠지", "어쩐지", "어딘가" 남용 금지
A7. 쌍점(:)·줄임표(...) 남용 금지
A8. 복합문 연쇄 (한 문단 내 쉼표 4개 이상) 금지
A9. 수식어 없이 명사로 끊기를 시도
A10. "~하는 것이었다" 구문 최소화
A11. 행동·발화·묘사·내면의 리듬 섞기
A12. 같은 단어 한 문단 내 2회 이상 반복 주의
A13. 설명조 ("~이기 때문이다") 지양, 보여주기
A14. 안전한 결말·원만한 합의·도덕적 정리 거부

## 무협 전용 규칙 (A15~A20) ⭐
A15. 한자 병기 — 반복은 금지, 부재는 더 큰 위반 (v2.6.0 재정의)
  금지 대상은 "같은 용어의 반복 병기"와 "일반명사 병기"다.
  고유명사(초식·무공·문파·기보·무기·학교·대회) 첫 등장 병기는
  무협 장르의 필수 신호이며 절대 생략하지 않는다.
  - (O) 첫 등장 "축지법(縮地法)" → 이후 전부 "축지법"
  - (X) 축지법(縮地法) … 다시 축지법(縮地法) — 반복 병기
  - (X) 안개(霧) 속에서 / 소년(少年)이 — 일반명사 병기
  - (X) 초식·문파 이름을 한글로만 처리 — 장르 신호 소실
  회차당 병기 8~15회가 정상. 4회 미만은 장르 계약 위반이다.
A16. 사자성어 남발 금지. 풀어쓰기 권장.
  단, 무공·경지·기세를 가리키는 4자 고유명사는 사자성어가 아니다.
  (살기충천·운기조식·주화입마는 장르 어휘이므로 제한 대상이 아니다)
A17. 고어체 (재하·소생·본좌) 무의식 사용 금지
A18. 무공 이름을 영문 의역 금지 ("Sky Sword"가 아니라 "천검")
A19. 경지를 숫자로만 표현 금지 (시스템 무협 아닌 이상)
A20. "강호의 이치가 그러하다"류 작가 개입 최소화

## 서사 구조 룰 (A21~A22) ⭐⭐ — v2.1.0 신규

A21. 1차/2차 위기 구조 (50% 이후 회차에서 의무)
  무협 후반부 긴장 곡선은 반드시 두 층으로:
  - 1차 위기 (메인플롯, 50~65% 지점, 50화 기준 EP25~32):
    · 사형 갈등·무공 봉인·일시적 좌절 같은 감정 차원
    · 해소: 본인의 자각 → 한 단계 깊은 결의
  - 2차 위기 (서브플롯, 75~85% 지점, 50화 기준 EP37~42):
    · 정사대전·마교 본격 등장·사문 멸문 같은 세계 규모
    · 핵심 질문: "모든 것을 잃어도 이 길을 갈 것이냐?"
    · 해소: 모든 것을 걸고 결단 → 진정한 무도(武道) 완성
  주의: 1차 없이 2차로 가면 감정 빌드 약화. 2차 없으면 후반 추진력 부족.

A22. 첫 장면 9유형 (EP1·EP2에서 의무 선택)
  도입부는 다음 9유형 중 반드시 하나에 속한다.
  [독자를 마중하는 유형 — 정통계열에 적합]
    · 인물제시형: 주인공 캐릭터를 먼저 보여줌 (F4 학원무협 권장)
    · 일상제시형: 평화로운 일상 → 균열 (F6 정통강호 권장)
    · 배경제시형: 강호 풍경 → 사건 (F6 정통강호 권장)
    · 회상형: 과거 회상으로 시작 (F1 회귀·F2 이세계 권장)
    · 전체압축형: 핵심 갈등 압축 제시 (모든 공식)
  [독자를 유혹하는 유형 — 판타지계열에 적합]
    · 사건발생형: 결정적 사건이 먼저 터짐 (F1 회귀 권장 — 회귀 순간)
    · 행동형: 특이 행동·습관으로 시작 (F4 학원무협 권장)
    · 대비상징형: 강자/약자 대비 (F5 여성향 권장)
    · 의문유발형: 미스터리 던지기 (F3 시스템·F2 이세계 권장)
  주의: 9유형 중 하나에 속하지 않는 모호한 도입부는 흡인력 부족.

## 문체 룰 (A23~A24) ⭐⭐ — v2.2.0 신규

A23. 계측·관찰 리포트체 금지
  서술자가 계측기·분석 카메라처럼 수치와 각도를 기록하는 문체는
  AI 문체의 대표 흔적이다. 다음을 전면 금지한다.
  - 시간 계측 서술 금지: "0.1초", "이 초쯤", "초당 세 곳",
    "삼 초 만에" 같은 초 단위 수치 표기. 속도감은 수치가 아니라
    감각과 결과로 표현한다.
    (X) 콧등을 지나 검첨까지. 0.1초.
    (O) 콧등을 스친 바람이 검끝에 닿기도 전이었다.
  - 각도·자세 분석 서술 금지: "각도는 ~ 자세였다", "어깨선",
    "발끝의 방향" 같은 동작 분해 리포트. 동작은 분해하지 말고
    한 호흡의 이미지로 보여준다.
  - 인지 부정 부연 금지: "본인은 그것을 의식하지 못했다",
    "자신은 느끼지 못했다" 같은 서술자의 계측 보고.
    인물이 모르는 것은 독자도 장면으로만 감지하게 한다.
  - 명사문 신원 삽입 금지: "얼굴은 최형근." 처럼 명사 종결
    단문으로 정보를 끼워 넣지 말 것. 이름·신원은 행동이나
    대사 속에서 자연스럽게 드러낸다. (A9의 명사 끊기는 리듬
    기법이지 정보 전달 수단이 아니다.)
  - "아주 미세하게", "미묘하게" 같은 정밀 관찰 부사 남용 금지.
  **예외 (v2.6.0) — 무공 시연 구간**
  A30의 ②시연 구간에서는 동작을 연속 시퀀스로 쓰는 것을 허용한다.
  무협의 초식 시연은 동작이 이어지는 것 자체가 볼거리다.
  금지되는 것은 "수치·계측·분해 리포트"이고, 허용되는 것은
  "한 호흡으로 이어지는 동작의 흐름"이다.
    (X) 손목 각도 15도. 어깨선이 반 박자 늦게 따라왔다.
    (O) 손목을 한 번 감았다가 풀자 아미자가 회전하기 시작했다.
        첫 마디가 펴지고 두 번째, 세 번째가 이어졌다.
  판별 기준: 문장에 숫자·각도·초 단위가 있으면 위반,
  동작 동사와 감각 비유로만 이어지면 허용이다.

A24. 설정 재료 반복 상한 (버릇·말버릇·습관·소지품)
  캐릭터에 설정된 버릇·습관·말버릇·상징 소품은 "존재 증명"이
  아니라 "필요할 때 꺼내는 카드"다. 설정을 매 장면 시연하는 것은
  AI 문체의 대표 흔적이다.
  - 설정된 버릇·습관의 실행 묘사: 회차당 최대 1~2회.
    플롯 기능이나 감정 전환에 복무할 때만 꺼낼 것. 기능이
    없으면 0회가 정답이다.
    (X) 메모 습관 설정 → 모든 행동 끝에 메모하는 묘사
    (O) 결정적 순간 1회, 메모가 서사를 움직이는 배치
  - 말버릇·습관 멘트(speech_samples의 반복 대사 포함):
    회차당 1회 이하. 매 대화마다 반복 금지.
  - 상징 소품(구슬·붉은 끈·손목시계 등) 확인 동작:
    회차당 최대 2회. 매 장면 소품을 만지작거리게 하지 말 것.
  - 같은 표현의 재등장은 간격을 벌릴수록 강해진다.
    반복은 리듬이 아니라 마모다.

## 타깃·장르 룰 (A25~A28) ⭐⭐⭐ — v2.3.0~v2.4.0

A25. 1020 타깃 경량화 (F4 학원무협·F3 시스템 무협 의무)
  10~20대 독자는 "관찰"이 아니라 "체험"을 원한다. 정적 묘사로
  분위기를 쌓는 문예 문체는 이 타깃에서 이탈을 만든다.
  - 대사 글자 비율 30% 이상 (지문:대사 = 7:3 최소, 6:4 권장).
    묘사만 이어지는 원고는 1020 타깃에서 실패한다.
  - 주인공 대사 회차당 12마디 이상. 무표정·침묵으로 쿨함을
    표현하지 말 것. 쿨함은 "말수 없음"이 아니라 "말의 태도"다.
    (X) 대답하지 않았다 / 대답은 하지 않았다 (반복 금지)
    (O) 짧고 건조하지만 분명한 대사로 응수
  - 관찰·묘사 문단 3개 연속 금지. 반드시 대사나 행동을 끼울 것.
  - 경쾌·유머 담당 인물이 회차당 최소 2회 기능 수행.
    (당하는 역할만 하는 조연은 유머 담당이 아니다)
  - 서술자가 인물 위에서 관찰하는 시점 고정 금지.
    주인공의 감각·판단·속마음에 밀착할 것.
  - 문장이 짧은 것과 템포가 빠른 것은 다르다. 템포는
    사건이 얼마나 자주 바뀌는가로 결정된다.
  **예외 (v2.6.0) — 무공 해설과 수련 공간**
  다음 두 구역은 "묘사 3연속 금지"의 예외이며, 회차당 각 1구역까지
  허용한다. 이 구역은 정적 분위기 쌓기가 아니라 장르 정보 전달이다.
    ① 무공 해설 구역 — A30의 ③해설. 초식의 원리·문파 귀속·
       장단점을 2~4문단 연속으로 서술할 수 있다.
    ② 수련 공간 도입 구역 — 도장·연무장·문파 산문을 처음 보여줄 때,
       그 공간에 쌓인 무림의 시간(칼자국·검기 흔적·닳은 바닥)을
       2~4문단 연속으로 서술할 수 있다.
  주의: 예외는 회차당 각 1회다. 두 번째부터는 다시 3연속 제한이
  적용된다. 그리고 예외 구역 직후에는 반드시 대사나 사건을 놓는다.

A26. 무협 액기스 (전 공식 매 회차 의무 / EP1·EP2 특히 엄격)
  무협 독자는 매 회차에서 "무협을 읽고 있다"는 확인을 원한다.
  분위기만 쌓고 무공이 나오지 않는 회차는 장르 계약 위반이다.
  - 무공 시전 최소 1회. 초식·무공 이름을 명시하고 시각적으로
    3문장 이상 묘사할 것. 이름 없는 몸싸움은 시전이 아니다.
  - 무기 격돌 또는 실제 타격 1회 이상. 검이 뽑히고 부딪히지
    않은 채 상황이 종료되는 전개 금지.
  - 경지·내공 체계를 대사나 묘사로 최소 1회 노출.
  - 적이 스스로 물러나는 방식으로 갈등을 끝내지 말 것.
    주인공의 행동이 결과를 만들어야 카타르시스가 생긴다.
  - 문파·학원의 무학 특색(무엇을 가르치고 무엇이 다른가)을
    구체적으로 제시.
  - 예외: 순수 감정 회차·일상 회차에서도 최소 무공 언급 1회는
    유지할 것 (완전 부재 금지).

A27. 초식 일관성·설명 룰 (매 회차)
  50화를 관통하는 무공 체계의 일관성은 무협의 신뢰도를 만든다.
  회차마다 이름이 바뀌는 무공은 독자를 이탈시킨다.
  - 이미 등장한 초식은 **같은 이름**으로 쓸 것. 유사 표현으로
    바꾸지 말 것. (X) 경천미러 → 반사경천 → 미러링
  - 이미 설명한 초식은 재설명 금지. 이름 + 효과만 짧게 처리.
  - 신규 초식 첫 등장 시 4요소 설명 의무:
    ① 이름 (한자 3~5자, 첫 등장만 한자 병기)
    ② 원리·계보 (1~2문장)
    ③ 시각적 형상 (2~3문장)
    ④ 대가·한계 (있으면 1문장)
  - 즉흥 작명 금지. 새로 만든 초식은 그 작품의 자산으로 고정된다.
  - 경지 체계는 작가가 확정한 이름만 사용. 새 등급을 만들지 말 것.
  - 초식 인플레 주의: 회차마다 새 초식을 남발하면 기존 초식의
    무게가 사라진다. 신규 초식은 서사적 이유가 있을 때만.
  **도입 구간 조항 (EP1~EP8) — v2.6.0**
  이 조항은 "인플레 주의"가 도입부에서 정반대로 작동한 사고를
  막기 위한 것이다. EP1~EP8은 초식 체계를 독자에게 처음 소개하는
  구간이므로 인플레 규정을 적용하지 않는다.
  - EP1~EP8에서는 초식 바이블에 있는 무공을 **적극적으로 꺼낸다.**
    이 구간의 신규 초식 등장은 인플레가 아니라 세계관 개장이다.
  - 억제해야 할 것은 "바이블에 없는 초식을 즉흥 작명하는 것"이며,
    "바이블에 있는 초식을 많이 쓰는 것"은 억제 대상이 아니다.
  - EP9 이후부터 인플레 규정을 정상 적용한다.

A28. 작가 설정 우선 룰 (매 회차 — v2.4.0)
  기획서에 이미 존재하는 고유명사를 관용어로 바꾸는 것은
  작품의 차별화 장치를 지우는 행위다.
  - **초식 바이블·세계관 블록에 있는 고유명사는 철자를 그대로 쓴다.**
    인물명·문파명·학교명·초식명·무기명·기보명·대회명 전부.
  - 작가가 관용 한자와 다르게 표기한 경우를 존중한다.
    (華山 → 花山 / 武當 → 武螳 / 峨嵋 → 阿美 같은 의도적 변경)
  - **무협 관용 초식명으로 대체 금지.** (X) 자하신공·태극혼원공·
    구양신공 같은 일반명을 작가 설정 초식 자리에 넣는 것
  - 바이블에 없는 인물·조직·초식을 새로 만들지 않는다. 서사상
    꼭 필요하면 A27의 4요소 설명을 붙여 도입하고 이후 고정한다.
  - 소품·기보는 그 정체가 밝혀지는 시점(reveal_timing)을 지킨다.
    아직 밝혀지지 않은 물건은 이름을 부르지 않고 형태로만 쓴다.

## 장르 밀도 룰 (A29~A31) ⭐⭐⭐⭐ — v2.6.0 신규 · 최우선

A29. 무협 밀도 하한 (전 회차 / EP1~EP4 강화)
  [이 룰이 왜 최우선인가]
  독자는 1~4화에서 "이게 무협인가"를 판정하고 이탈한다. 문장이
  좋아도 장르 신호가 없으면 무협 독자는 남지 않는다. 분위기·감정·
  대사 리듬이 뛰어난 회차가 무협으로 읽히지 않는 사고가 실제로
  발생했다. 원인은 다른 룰(A15·A23·A25·A27)의 절제 지시를
  장르 신호까지 줄이는 지시로 확대 적용한 것이었다.
  **A29는 다른 모든 절제 룰보다 우선한다.** 절제 룰과 충돌하면
  A29를 따른다.

  ### 회차당 정량 쿼터 (하한이 아니라 목표값)
  | 항목 | EP1~EP4 | EP5 이후 |
  |---|---|---|
  | 이름이 붙은 무공·초식 시전 | 5종 이상 | 3종 이상 |
  | 고유명사 한자 병기 (첫 등장) | 8~15회 | 6~12회 |
  | A30 3박자 완주 | 2회 이상 | 1회 이상 |
  | 문파·계보 귀속 명시 | 3회 이상 | 2회 이상 |
  | 내공·기의 가시화 문장 | 4회 이상 | 3회 이상 |
  | 타격·풍압 의성어 | 3회 이상 | 2회 이상 |
  | 경지·서열 노출 | 2회 이상 | 1회 이상 |

  쿼터를 채우고 멈추지 말 것. 위 숫자는 "이 정도는 반드시"이고
  상한이 아니다. 상업 무협 원고의 실측 밀도는 이 표의 1.5~2배다.

  ### 절대 금지
  - **이름 없는 몸싸움을 무공 시전으로 처리하는 것.**
    관절을 꺾고 명치를 누르는 격투는 현대 액션이지 무협이 아니다.
  - **무공에 이름이 없다는 사실을 서사 장치로 쓰면서 실제 이름을
    끝까지 제시하지 않는 것.** 주인공이 자기 무공의 이름을 모르는
    설정은 훌륭하다. 단, 그 회차 안에서 **다른 인물이 이름을
    붙여줘야** 한다 (A30 명명 책임 이전 조항).
  - 무공을 "그냥 됐다"로 처리하고 넘어가는 것. 원리 한 줄은
    반드시 붙는다.
  - 전투를 대사 핑퐁으로 대체하는 것. 대사가 늘어난 만큼
    무공이 줄면 장르가 빠져나간다.

A30. 무공 3박자 문법 — 명명 → 시연 → 해설 (매 회차 의무)
  이것이 무협 산문의 서명 문법이다. 세 박자 중 ③이 빠지면
  무협이 아니라 판타지 액션이 된다. 무협 독자가 지갑을 여는
  지점은 ③이다.

  ① **명명** — 이름을 소리 내어 부른다
     대사로 외치거나, 지문으로 선언한다. 첫 등장은 한자 병기.
     (O) "먼저, 무당파의 당랑연검술(螳螂軟劍術)!"
     (O) 축지법(縮地法). 땅을 접어 거리를 줄이는 보법이었다.
     대사로 부르는 편이 지문 선언보다 강하다. 둘을 섞어 쓴다.

  ② **시연** — 눈에 보이게 한다 (2~4문장)
     동작을 자연물·일상 사물의 비유로 번역한다. 추상어 금지.
     비유의 원본은 그 무공의 이름 안에 이미 들어 있다.
     (O) 사마귀의 앞발처럼 정확히 찌르고, 더듬이처럼 유연하게
         상대의 검을 흘렸다.
     (X) 강력한 기운이 폭발적으로 뻗어나갔다. (추상·형용사)

  ③ **해설** — 원리·귀속·장단점 (2~4문장) ★엔진이 가장 자주 빠뜨림
     다음 네 요소 중 최소 3개를 문단으로 서술한다.
       · 원리 — 무엇을 모방했고 무엇을 이용하는가
       · 계보·귀속 — 어느 문파의 무엇인가, 누가 쓰는가
       · 강점 — 어떤 상황에서 강한가
       · 대가·한계 — 무엇을 내주는가, 언제 통하지 않는가
     (O) 당랑연검술은 사마귀의 움직임을 연구해 만든 연검술이다.
         정면으로 맞서지 않고 상대의 힘을 흘려보낸 뒤 되돌려준다.
         상대의 내공이 강할수록 되돌아가는 힘도 커진다. 다만
         검이 유연한 만큼 단단한 방어를 뚫는 데는 약하다.
     해설은 서술자가 독자에게 직접 설명해도 된다. A20(작가 개입
     최소화)의 예외다. 무협 독자는 이 설명을 기대하고 읽는다.
     해설을 대사로 처리하면 더 좋다 (스승·조력자·해설 캐릭터).

  ### 명명 책임 이전 조항
  주인공이 무학 계보가 없는 유형(정통_주인공 노력형·야인형 등)이면
  ①명명과 ③해설의 책임을 **다른 인물에게 넘긴다.**
    - 스승·교사가 이름을 붙여준다:
      "혜성스님이 정심무동(靜心無動)을 가르쳤구나."
    - 정보 담당 조연이 감정한다: "그거 경공술 아니야. 축지법이야."
    - 라이벌이 알아본다: "화산진검(花山盡劍)의 갈래를 어디서 봤지?"
  주인공이 모르는 것은 좋다. 독자가 모르고 넘어가는 것은 실패다.

  ### 3박자를 압축하는 경우
  이미 등장한 초식의 재사용에서는 ①+②만 쓰고 ③을 생략한다
  (A27 재설명 금지). 단 회차당 최소 1~2회는 신규 초식으로
  3박자를 완주해야 한다.

A31. 강호 좌표와 몸의 소리
  ### 문파 귀속으로 강호 지도를 그린다
  - 무공을 부를 때 소속을 붙인다. "무당파의 당랑연검술",
    "화산파가 자랑하는 화산장풍도". 소속 없는 초식명은
    강호에 좌표가 없다.
  - 회차당 최소 2~3개 문파·학교의 이름이 언급되어야 강호가
    넓게 느껴진다. 우리 편만 나오면 세계가 좁아진다.
  - 문파 이름은 대사 안에서 자연스럽게 흘린다. 설정 나열 금지.

  ### 경지·서열은 감각으로 노출한다
  - 숫자·등급표 금지 (시스템 무협 제외). 대신 상대의 반응으로
    보여준다. "화경의 감각으로도 이 아이의 그릇이 잡히지 않았다."
  - 강자가 약자를 볼 때의 여유, 약자가 강자를 볼 때의 압력.
    서열은 대사의 태도로 드러난다.

  ### 의성어 — 무협은 소리가 나는 장르다
  - 타격·풍압·검격에 의성어를 인용 표기로 넣는다.
    '휙' '쏴아' '붕' '쩌렁' '휘릭' '우웅'
  - 회차당 2~3회. 남발하면 만화가 되고, 없으면 무성영화가 된다.
  - 인용부호로 감싸 독립 배치하면 리듬이 끊기며 타격감이 생긴다.

  ### 내공은 보이게 쓴다
  - "내공이 강했다"가 아니라 내공이 무엇을 했는지 쓴다.
    단전에서 올라온 목소리가 사방으로 퍼지는 것, 손끝의 기운이
    허공에 궤적을 남기는 것, 나뭇잎이 기세에 떨리는 것.
  - 운기조식·기맥·단전 같은 신체 어휘를 회차당 3~4회 쓴다.

A32. 문장 선두 기호 금지 — 말줄임표·대시 (매 회차 / 절대 규칙)
  AI가 쓴 한국어 소설을 독자가 알아보는 가장 빠른 단서가
  문장 맨 앞의 기호다. 뜸을 들이는 리듬을 기호로 대신하려는
  버릇인데, 실제 작가는 이 자리를 문장으로 채운다.

  ### 금지 1 — 대사 선두 말줄임표
  - 금지: "……저건 뭐예요."  "…뭘요."  "...네."
  - 정정: "저건 뭐예요."  "뭘요."  "네."
  - 망설임·머뭇거림은 기호가 아니라 앞뒤 지문으로 만든다.
    · 지문 선행:  지훈이 대답을 찾지 못했다. / "저건 뭐예요."
    · 동작 삽입:  "저건." 지훈이 침을 삼켰다. "뭐예요."
    · 그냥 둔다:  대사만 툭 놓아도 독자는 정황으로 읽는다.
      → 셋 중 아무것도 못 쓰겠으면 그냥 두는 쪽을 고른다.

  ### 금지 2 — 문단 선두 대시
  - 금지: ——그런데 몸이 생각보다 멀리 갔다.
          ——20년 전.
  - 정정: 그런데 몸이 생각보다 멀리 갔다.
          20년 전.
  - 전환·회상·반전을 대시로 표시하지 않는다. 줄 바꿈과
    문장 자체가 이미 전환 신호다.
  - 시간 점프는 명사구 한 줄로 충분하다. ("20년 전.")

  ### 허용 범위
  - 문장 '중간·끝'의 말줄임표는 허용한다. 다만 A7에 따라
    회차당 총량은 절제한다. ("그러니까, 그게……")
  - 문장 중간의 대시(삽입구·말 끊김)는 허용한다.
    ("그건—" 하고 말이 끊기는 경우)
  - 즉, 금지되는 것은 오직 '문장·대사가 기호로 시작하는 것'이다.

  ### 장면 구분선
  - 장면 전환에는 *** 한 줄만 쓴다. 다른 기호를 섞지 않는다.
    (DOCX 출력 시 자동으로 가운데 정렬된다)

A33. 세계 유형 · 판타지 수위 정합 (매 회차 / 절대 규칙) — v2.9.0 신규
  작품마다 세계 유형(현대_무림 / 중원_강호 / 조선_역사)과 판타지
  수위(0~3)가 정해져 있다. 둘 다 프롬프트의 "세계 유형" 블록에 있다.

  ### 금지 1 — 시대착오
  - 현대 무림: 냥·문·전·관 화폐, 자시·축시·일각·시진 표기, 왕조 관직 금지
  - 조선 역사: 구파일방·마교·무림맹 같은 중원 무협 세력, 작품 연도보다
    늦게 성립한 문헌·제도, 바이블에 없는 실존 인물의 관직·연대 금지
  - 중원 강호: 휴대폰·자동차·현대 화폐 등 현대 문물 금지
    (이세계·시스템 장치로 작품이 명시한 경우만 예외)

  ### 금지 2 — 수위 초과
  - 판타지 수위 블록의 '사용 금지 표현'을 쓰지 않는다.
  - 클라이맥스 구간(수위 상향 회차) 전에 상위 수위 장면을 앞당기지 않는다.
    초월이 일찍 나오면 클라이맥스의 무게가 사라진다.

  ### 금지 3 — 미정 설정 창작
  - 세계관 바이블의 '미정 항목'에 해당하는 새 기관·새 규칙·새 수치를
    본문에서 만들어 내지 않는다. 필요하면 그 대목을 피해 간다.
"""


# ═══════════════════════════════════════════════════
# 웹소설 문체 규칙 (무협 버전)
# ═══════════════════════════════════════════════════

WEB_NOVEL_PROSE_RULES = """[무협 웹소설 문체 규칙]

## 기본 원칙
1. 한 문단 3~4문장 이내 (모바일 가독성)
2. 단문 중심, 중장문은 감정·묘사 시만
3. 지문 : 대사 = 6 : 4 혹은 5 : 5
4. 첫 줄은 짧게 (클릭 유도)

## 전투 장면 (무협 핵심) — 3층 구조 (v2.6.0 개편)
초단문만으로 전투를 쓰면 현대 액션·하드보일드가 된다. 무협 전투는
아래 세 층을 반드시 섞는다. 한 층만 쓰면 장르가 빠져나간다.

### 1층 · 초단문 (타격과 결과)
- "검이 번쩍였다." "둘이 동시에 흙을 물었다."
- 시각적 동사: 휘둘렀다, 내리쳤다, 꿰뚫었다, 베어냈다, 찔러 들어갔다
- 의성어 인용 배치로 타격감: '붕' '쩌렁' '휙'

### 2층 · 초식 시퀀스 (볼거리 — A30 ②시연)
- 이름을 부른 뒤 그 동작을 2~4문장으로 이어서 보여준다.
- 동작을 자연물·사물의 비유로 번역한다.
  "첫 마디가 펴지자 두 번째, 세 번째가 이어졌다. 꽃잎이 겹쳐
   피는 것 같았다. 손목을 안쪽으로 꺾자 열두 마디가 일제히 닫혔다."
- 이 층이 없으면 독자는 무공을 본 것이 아니라 결과만 통보받는다.

### 3층 · 해설 (과금 지점 — A30 ③해설)
- 그 무공이 무엇인지 서술자나 인물이 설명한다.
  원리 · 문파 귀속 · 강점 · 대가.
- 전투 직후 호흡을 고르는 대목에 배치하면 리듬이 산다.

### 층 배치 리듬
2층 → 1층 → 3층 → 1층 순으로 감으면 가장 안정적이다.
(시연으로 보여주고 → 짧게 때리고 → 정체를 알려주고 → 마무리)
- 감각 교차: 시각 → 청각 → 촉각
- 호흡: 교전 중 중단 없이, 승부 후 휴식 호흡에서 3층 배치

## 무공 명명
- 한자 3~5자 간결
- 자연 + 동작 (풍운변색, 만검귀종)
- 신화 + 기술 (청룡출수, 백호연풍)
- 글로벌 친화 (번역 시 3어절 이내)
- **첫 등장 시 한자 병기 필수.** 이름을 한글로만 쓰면 무협
  고유명사가 아니라 일반 용어로 읽힌다.
- **초식 바이블에 이름이 있으면 그 이름을 쓴다.** 이름을 새로
  만들지도, 이름 없이 넘기지도 않는다.

## 경지 묘사
- 숫자보다 감각 ("단전이 끓었다", "혈도를 따라 열기가 흘렀다")
- 시스템 무협은 숫자 허용
- 회차당 최소 1~2회는 경지 이름을 명시한다. 감각 묘사만 있고
  경지 어휘가 없으면 무협 서열 구조가 독자에게 전달되지 않는다.

## 감정 장면
- 중문 허용
- 내면 독백 활용
- 환경 묘사로 감정 대신 표현
"""


