AUTHOR_STYLE_DNA_BASE = """Mr. MOON 스타일 기본 규칙:
- 지문은 건조하고 간결
- 대사는 캐릭터별 말투 선명
- 감정은 폭발시키기보다 행동·환경으로
- 클리셰 회피, 예상 밖 전환 선호
- 한자 병기 최소 (첫 등장만)
- 사자성어보다 현대어 선호
"""


def _style_block(style_dna, strength="중"):
    """스타일 DNA 블록 생성."""
    if not style_dna:
        style_dna = AUTHOR_STYLE_DNA_BASE

    strength_desc = {
        "강": "이 스타일을 강하게 반영. 모든 문장에서 느껴지도록.",
        "중": "이 스타일을 고루 반영하되, 서사 흐름 우선.",
        "약": "이 스타일을 배경으로만 반영.",
    }.get(strength, "이 스타일을 고루 반영.")

    return f"## 작가 스타일 DNA\n{style_dna}\n\n적용 강도: {strength_desc}"


def _pn_block(producer_note):
    """프로듀서 노트 블록."""
    if not producer_note or not producer_note.strip():
        return ""
    return f"## 프로듀서 노트 (최우선 지시)\n{producer_note.strip()}"


def _genre_block(genre):
    """장르 규칙 블록."""
    genre_key = detect_genre_key(genre)
    return f"## 장르 설정: {genre}\n\n" + get_genre_rules_block(genre_key)


def _rating_block(rating):
    """등급 블록."""
    if rating == "19금":
        return "## 등급: 19금\n폭력·관능 디테일 허용. 서사적 필연성 있을 때."
    return "## 등급: 15금\n혈흔 제한. 관능은 암시 수준. 전 플랫폼 호환."


